#ifndef _HUDFILTER_H
#define _HUDFILTER_H

/*
 * These methods are implemented by all base nodes, currently
 * TCP and UDP
 */
enum hudnode_method {
    HUDNODE_METHOD_GET_FLOW,
    HUDNODE_METHOD_COUNT
};

/*
 * The hudsucker framework is a modular system for networking within
 * the microkernel. The processing components in the system are called
 * filters. Each filter has a process routine that processes ingress
 * packets from the lower-lever filter and egress packets from the
 * upper-level filter.  Each filter also has a handler that processes
 * event notifications from the lower-level filter and control
 * messages from the upper-level filter. To put it another way, a
 * hudfilter is a link in a packet-processing chain.
 */
struct hudproxy;
struct profile_key;
struct tmevt;
struct xbuf;
struct pkt_queue;
struct hudnode;
struct hudfilter;
struct profile_listener;
union uflow;

typedef err_t (*hud_init)(struct hudfilter *this, struct hudproxy *proxy);
typedef void  (*hud_uninit)(struct hudfilter *this);
typedef void  (*hud_handler)(struct hudnode *node, hud_msg_t msg,
        struct connflow *cf, void *data);
typedef err_t (*hud_processor)(struct hudnode *node, struct connflow *cf,
        struct xbuf *xb);
typedef err_t (*hud_process_pkt)(struct hudnode *node, struct connflow *cf,
        struct packet *pkt);
typedef void (*stream_handler)(struct hudnode *snode, hud_msg_t msg,
        union uflow *uf, void *data);
typedef err_t (*stream_processor)(struct hudnode *node,
        union uflow *uf, struct xbuf *xb);

/*
 * Bottom level filters begin at 0 and increase to UINT16_MAX
 * at the proxy filters.
 */
#define HUDFILTER_BOTTOM_INDEX               0
#define HUDFILTER_PROXY_INDEX                (UINT16_MAX - 1)
#define HUDFILTER_PROXY_MOCK_INDEX           UINT16_MAX
