static inline void
uflow_handle_lower(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    /*
     * Pending async operations can hold a reference to a node beyond the life
     * of the node itself.  Which is fine.  But if the node tries to contact
     * others in the chain, then the messages should be dropped.
     */
    struct hudnode *next = node->below;
    if (next != NULL) {
        hud_msg_log("uflow lower", msg, uf, next, data);
        next->h_s_handler(next, msg, uf, data);
    }
}

static inline void
uflow_handle_upper(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
