     * of the node itself.  Which is fine.  But if the node tries to contact
     * others in the chain, then the messages should be dropped.
     */
    struct hudnode *next = node->above;
    if (next != NULL) {
        hud_msg_log("uflow upper", msg, uf, next, data);
        next->h_s_handler(next, msg, uf, data);
    }
}

