/*
 * Create a streamnode, using a hudnode as a template.
 */
static struct hudnode *
streamnode_create(struct hudnode *node, BOOL is_clientside)
{
    struct hud_typeid *typeid;
    struct hudfilter_base *base;
    struct hudnode *snode = NULL;
    struct hudproxy *ptemplate;
    struct hudfilter *template, *tmp;

    if (HUDNODE_IS_TOP(node)) {
        typeid = HUDNODE_PROXY_TYPEID(node);
        ptemplate = typeid->template;
        if (ptemplate == NULL) {
            goto out;
        }
        if (HUDNODE_IS_CLIENTSIDE(node)) {
            tmp = HUDNODE_FILTER(ptemplate->clientside);
            base = &tmp->base;
        } else {
            tmp = HUDNODE_FILTER(ptemplate->serverside);
            base = &tmp->base;
        }
    } else {
        typeid = HUDNODE_TYPEID(node);
        template = typeid->template;
        if (template == NULL) {
            goto out;
        }
        base = &template->base;
    }

    if (node->f_orbit) {
        char *p = umem_alloc(sizeof(struct hudnode) + base->scb_sz +
                HUD_ORBIT_SIZE, M_STREAM, 0);
        if (p != NULL) {
            snode = (void *)&p[HUD_ORBIT_SIZE];
        } else {
            snode = NULL;
        }
    } else {
        snode = umem_alloc(sizeof(struct hudnode) + base->scb_sz, M_STREAM, 0);
    }
    if (snode == NULL) {
        goto out;
    }

    snode->h_s_handler = node->h_s_handler;
    snode->s_ingress = node->s_ingress;
    snode->s_egress = node->s_egress;
    snode->above = NULL;
    snode->below = NULL;

    if (HUDNODE_IS_STREAM(node)) {
        snode->parent = node->parent;
    } else {
        snode->parent = HUDNODE_CTX(node);
    }
    snode->private = node->private;
    snode->ref = 0;

    snode->ctx_sz = base->scb_sz;

    /* Copy the flags from the corresponding hudnode */
    snode->f_disabled = node->f_disabled;
    snode->f_clientside = node->f_clientside;
    snode->f_serverside = node->f_serverside;
    snode->f_top = node->f_top;
    snode->f_bottom = node->f_bottom;
    snode->f_no_abort = node->f_no_abort;
    snode->f_active = TRUE;
    snode->f_ctx = TRUE;
    snode->f_stream = TRUE;
    snode->f_orbit = node->f_orbit;
    snode->f_no_prime = node->f_no_prime;
    snode->f_scratch1 = node->f_scratch1;

    memset(snode->ctx, 0, base->scb_sz);

    if (snode->f_orbit) {
        hud_orbit_stream_init(snode, node);
    }

out:
    return snode;
}

/*
 * Insert a new active node derived from 'filter' in the chain referenced by
 * 'node'.
 */
struct hudnode *
uflow_insert_node(struct hudnode *node, struct hudnode *source,
        struct hud_typeid *filter, union uflow *uf, BOOL beneath,
        void *data, SIZE size_override)
{
    struct hudnode *hf, *ins = NULL;
    struct hudfilter_base *base;
    SIZE size = size_override;
    mem_type type;

    if ((uf != NULL) && uflow_test_flag(uf, CONNFLOW_FLAG_DYING)) {
        goto out;
    }

    /* Find the prototype for this node. */
    hf = hud_find_node(source, filter, below);
    if (hf == NULL) {
        goto out;
    }

    base = &HUDNODE_FILTER(hf)->base;
    if (uflow_isconnflow(uf)) {
        if (size == 0) {
            size = base->pcb_sz;
        }
        type = M_FILTER;
    } else {
        if (size == 0) {
            size = base->scb_sz;
        }
        type = M_STREAM;
    }

    if (hf->f_orbit) {
        char *p = umem_alloc(sizeof(struct hudnode) + size + HUD_ORBIT_SIZE,
                type, UM_ZERO);
        if (p != NULL) {
            /* The node is at offset HUD_ORBIT_SIDE in the allocated block */
            ins = (void *)&p[HUD_ORBIT_SIZE];
        } else {
            ins = NULL;
        }
    } else {
        ins = umem_alloc(sizeof(struct hudnode) + size, type, UM_ZERO);
    }
    if (ins == NULL) {
        goto out;
    }

    ins->f_ctx = (size != 0);
    ins->ctx_sz = size;

    if (uflow_isconnflow(uf)) {
        hudproxy_addref(base->proxy);
        hudnode_addref(hf);
        ins->f_stream = FALSE;
    } else {
        /*
         * Streams don't need to ref the proxy or the private,
         * as their parent connection will keep them alive.
         */
        ins->f_stream = TRUE;
    }

    ins->h_handler = hf->h_handler;
    ins->ingress = hf->ingress;
    ins->egress = hf->egress;
    ins->f_disabled = hf->f_disabled;
    ins->f_clientside = hf->f_clientside;
    ins->f_serverside = hf->f_serverside;
    ins->f_top = hf->f_top;
    ins->f_bottom = hf->f_bottom;
    ins->f_active = TRUE;
    ins->f_orbit = hf->f_orbit;
    ins->private = hf->private;

    if (beneath) {
        node = HUDNODE_NEXT(node, below);
    }

    /* Send FLOW_INIT so the node can self-initialize */
    uflow_handle(ins, HUDEVT_FLOW_INIT, uf, NULL);

    /*
     * Inform orbit that this node was inserted on an active chain.
     * We don't know the complete flow-control state, so HUDEVT_SENT
     * needs to be forwarded up the chain, even if we have no work
     * to do.
     */
    if (ins->f_orbit) {
        hud_orbit_late_insert(ins);
    }

    /* Insert the node in the chain */
    hudnode_insert(node, ins);

out:
    return ins;
}

void
streamflow_release_(struct streamflow *sf)
{
    union uflow *uf = uflow_fromstreamflow(sf);

    Tcl_AfterCancelByUF(uf, sf->tclpcb);

    /* Free the "child" tclpcb */
    if (sf->tclpcb != NULL) {
        tclrule_stream_release(sf->tclpcb);
    }

    /* Free the opaque data */
    uflow_opaque_delete_all(uf);

    /* Remove all nodes. */
    while (sf->bottom_node != NULL) {
        hudnode_remove(uf, sf->bottom_node);
    }

    hudnode_swapref(&sf->bottom_node, NULL);
    hudnode_swapref(&sf->top_node, NULL);

    flow_release(sf->cf);
    umem_cache_free(streamflow_cache, sf);
}

/*
 * Create a streamnode chain, starting at the given hudnode, and
 * proceeding upwards to the proxy.  The bottom_node will contain
 * the streamnode corresponding to the given hudnode.
 */
struct streamflow *
stream_create(union uflow *uf, struct hudnode *node, UINT64 stream_id)
{
    err_t err;
    struct connflow *cf = uflow_get_connflow(uf);
    BOOL is_clientside = IS_CLIENTSIDE(cf);
    struct hudnode *snode;
    struct streamflow *sf = umem_cache_alloc(streamflow_cache, 0);
    if (unlikely(sf == NULL)) {
        /* low memory */
        goto out;
    }

    sf->cf = cf;
    flow_addref(cf);
    sf->bottom_node = NULL;
    sf->top_node = NULL;
    sf->tclpcb = NULL;
    sf->tmmrule_events = cf->tmmrule_events;
    sf->tm_opaque_table = NULL;
    sf->stream_id = stream_id;
    sf->peer = NULL;

    /* The owner has one ref */
    sf->ref = 1;

    /* Inherit information from the cf */
    sf->flags = cf->flags;
    sf->flow_type = cf->flow_type;

    /* Allocate the nodes */
    snode = streamnode_create(node, is_clientside);
    if (snode == NULL) {
        sf->top_node = NULL;
        sf->bottom_node = NULL;
        streamflow_release_(sf);
        sf = NULL;
        goto out;
    }

    sf->top_node = snode;
    sf->bottom_node = snode;
    snode->ref = 2;

    while (1) {
        node = node->above;
        if (node == NULL) {
            break;
        }

        snode = streamnode_create(node, is_clientside);
        if (snode == NULL) {
            streamflow_release_(sf);
            sf = NULL;
            goto out;
        }

        sf->top_node->above = snode;
        snode->below = sf->top_node;

        /* Two references to the node */
        snode->ref = 2;

        /* This is the new top node */
        sf->top_node = snode;
    }

    /* Duplicate the TCL context */
    err = tclrule_stream_create(uflow_fromstreamflow(sf),
            &sf->tclpcb, uflow_tclpcb(uf));
    if (err != ERR_OK) {
        streamflow_release_(sf);
        sf = NULL;
        goto out;
    }

    /* Duplicate the CPM context */
    err = policy_flow_dup(uflow_fromstreamflow(sf), uf);
    if (err != ERR_OK) {
        streamflow_release_(sf);
        sf = NULL;
        goto out;
    }

out:
    return sf;
}

/*
 * Search related flows and spawn parent for the opaque.
 */
void *
uflow_opaque_find_recursive(union uflow *uf, enum tm_opaque_id id)
{
    void *opaque = NULL;
    union uflow *peer;
    struct connflow *cf;

    while (uf != NULL) {
        opaque = uflow_opaque_get(uf, id);
        if (opaque != NULL) {
            break;
        }

        peer = uflow_peer(uf);
        if (peer != NULL) {
            opaque = uflow_opaque_get(peer, id);
            if (opaque != NULL) {
                break;
            }
        }

        cf = uflow_get_connflow(uf);

        opaque = flow_opaque_loop_find(cf, id);
        if (opaque != NULL) {
            break;
        }

        if (peer != NULL) {
            opaque = flow_opaque_loop_find(uflow_get_connflow(peer), id);
            if (opaque != NULL) {
                break;
            }
        }

        /* Try again with spawn parent */
        uf = uflow_fromconnflow(spawn_parent_flow(cf));
    }

    return opaque;
}

UINT64
uflow_get_streamid_aux(union uflow *uf)
{
    struct hudvariant result;
    struct method_data md;
    UINT32 stream_id = 0;

    hudvariant_init(&result);

    md.typeid   = &hudfilter_http2_typeid;
    md.methodid = HTTP2_METHOD_GET_STREAMID;
    md.argc     = 0;
    md.argv     = NULL;
    md.result   = &result;

    uflow_handle(uflow_bottom_node(uf), HUDCTL_PERFORM_METHOD, uf, &md);

    if (!hudvariant_is_error(&result)) {
        /* Pass the value as a pointer-sized type as it may be 64 bits */
        stream_id = INT(hudvariant_get_ptr(&result));
    }

    hudvariant_uninit(&result);

    return stream_id;
}

union uflow *
uflow_lookup_stream_aux(struct connflow *cf, UINT64 stream_id)
{
    struct hudvariant result;
    struct hudvariant argv;
    struct method_data md;
    union uflow *uf = NULL;

    hudvariant_init(&argv);
    hudvariant_init(&result);

    md.typeid   = &hudfilter_http2_typeid;
    md.methodid = HTTP2_METHOD_GET_STREAM;
    md.argc     = 1;
    md.argv     = &argv;
    md.result   = &result;

    /* Pass as a pointer-sized type because it may be 64 bits */
    hudvariant_set_ptr(&argv, PTR(stream_id));

    hud_proxy_handle(HUDCTL_PERFORM_METHOD, cf, &md);

    if (!hudvariant_is_error(&result)) {
        uf = hudvariant_get_ptr(&result);
    }

    hudvariant_uninit(&argv);
    hudvariant_uninit(&result);

    return uf;
}

