STATIC_ASSERT(sizeof(struct hudnode) == CACHE_ALIGN);
STATIC_ASSERT(offsetof(struct hudfilter, node) == 0);
STATIC_ASSERT(offsetof(struct hudfilter, base) == CACHE_ALIGN);

struct hudnode *
hudnode_alloc_raw(SIZE pcb_sz, BOOL orbit)
{
    struct hudnode *node;

    pcb_sz = P2ROUNDUP(pcb_sz, (SIZE)64);

    ASSERT("pcb within constraints", pcb_sz < HUD_PCB_SZ_MAX);

    /*
     * Allocate the full hudnode for this shim.
     *
     * For now, 'ref' must be initialized to 0, and will be ref'ed on return.
     */
    if (orbit) {
        /* The orbit data is placed before the hudnode */
        char *p = umem_alloc(sizeof(struct hudnode) + pcb_sz +
                HUD_ORBIT_SIZE, M_FILTER, UM_ZERO);
        if (p != NULL) {
            node = (void *) &p[HUD_ORBIT_SIZE];
            node->f_orbit = TRUE;
        } else {
            node = NULL;
        }
    } else {
        node = (struct hudnode *)umem_alloc(sizeof(struct hudnode) + pcb_sz,
            M_FILTER, UM_ZERO);
    }
    if (node != NULL) {
        /* ctx_sz must always reflect the hudnode_cache index. */
        node->f_ctx = (pcb_sz != 0);
        node->ctx_sz = pcb_sz;
    }

    return node;
}

/*
 * Allocate a new connection context for the filter chain.
 * Returns a pointer to the context block for the given filter.
 */
struct hudnode *
hudnode_alloc(struct connflow *cf, struct hudnode *base_node, SIZE pcb_sz)
{
    struct hudfilter *filter = HUDNODE_FILTER(base_node);
    struct hudfilter_base *this = &filter->base;

    struct hudnode *node;

    node = hudnode_alloc_raw(pcb_sz, base_node->f_orbit);
    if (node == NULL) {
        goto out;
    }
    hudnode_init(filter, node);

    ASSERT("expected proxy", this->proxy > 0);
    ASSERT("expected ref", this->proxy->ref > 0);
    hudproxy_addref(this->proxy);

out:
    return node;
}

/*
 * Initialize the hudnode object based on the supplied filter prototype.  If
 * it's the filter's node itself, then supply the default handler, otherwise
 * copy the handler functions from the filter in preparation for handling
 * traffic.  Practically speaking, this should only be called outside of
 * hudnode_alloc for statically created (as part of a hudfilter) nodes.
 */
void
hudnode_init(struct hudfilter *filter, struct hudnode *node)
{
    struct hudnode *fn = &filter->node;

    node->private = filter->private;
    if (node != fn) {
        hudnode_set_handler(node, fn->h_handler);
        node->ingress = fn->ingress;
        node->egress = fn->egress;
        node->f_disabled = fn->f_disabled;
        node->f_clientside = fn->f_clientside;
        node->f_serverside = fn->f_serverside;
        node->f_orbit = fn->f_orbit;
        node->f_top = fn->f_top;
        node->f_bottom = fn->f_bottom;
        node->f_active = TRUE;
        node->f_stream = FALSE;
        hudnode_addref(fn);      /* Node ref's filter's private. */
    }
    /*
     * hudnode must be allocated into zero'ed memory, as 'ref' is assumed
     * correct at this point.
     */
}

void
hudnode_free(struct hudnode *node)
{
    struct hudproxy *proxy;

    hudproxy_dump(node);
    /*
     * Streams don't need to ref the proxy or the private,
     * as their parent connection will keep them alive.
     */
    if (HUDNODE_IS_ACTIVE(node) && !HUDNODE_IS_STREAM(node)) {
        /*
         * Release the reference on the private.  Non-filter-chain
         * inactive nodes not owned by the proxy will get deallocated
         * on hudnode_release(), so save a pointer to the proxy.
         */
        proxy = HUDNODE_PROXY(node);
        if (&HUDNODE_FILTER(node)->node != node) {
            hudnode_release(&HUDNODE_FILTER(node)->node);
        }
        hudproxy_release(proxy);
    }

    if (node->f_orbit && node->f_active) {
        void *orb = ((char *)node) - HUD_ORBIT_SIZE;
        umem_free(orb, sizeof(struct hudnode) + node->ctx_sz + HUD_ORBIT_SIZE,
                M_FILTER);
    } else {
        umem_free(node, sizeof(struct hudnode) + node->ctx_sz, M_FILTER);
    }
}

/*
 * Prune the segment of hudnodes from low to high of the hudchain for
 * connflow *cf. If high == NULL, the hudchain above low is removed.
 */
void
hudnode_prune(struct connflow *cf,
              struct hudnode *low, struct hudnode *high)
{
    if ((low == NULL) || (low == high)) {
        goto out; /* Nothing to do. */
    }

    /* Remove one hudnode at a time. */
    while (HUDNODE_NEXT(low, above) != high) {
        struct hudnode *next = NULL;

        /* Keep a ref of the hudnode. */
        hudnode_swapref(&next, low->above);
        if (next == NULL) {
            break;
        }

        /* Detach the next hudnode. */
        hudnode_swapref(&low->above, next->above);
        if (HUDNODE_NEXT(next, above) != NULL) {
            hudnode_swapref(&next->above->below, low);
        }
        hudnode_remove_above_below(next);
        hud_handle(next, HUDCTL_ABORT, cf, NULL);
        hudnode_swapref(&next, NULL);
    }

 out:
    return;
}

/*
 * Increment reference count.
 *
 * It is generally discouraged to call this function directly; use
 * hudnode_swapref instead.
 */
struct hudnode *
hudnode_addref(struct hudnode *node)
{
    if (node == NULL) {
        goto out;
    }

    node->ref++;

out:
    return node;
}

static inline void
streamnode_free(struct hudnode *snode)
{
    if (snode->f_orbit) {
        void *orb = ((char *)snode) - HUD_ORBIT_SIZE;
        umem_free(orb, sizeof(struct hudnode) + snode->ctx_sz + HUD_ORBIT_SIZE,
                M_STREAM);
    } else {
        umem_free(snode, sizeof(struct hudnode) + snode->ctx_sz, M_STREAM);
    }
}

/*
 * Decrement and free hudnode.
 *
 * It is generally discouraged to call this function directly; use
 * hudnode_swapref instead.
 */
struct hudnode *
hudnode_release(struct hudnode *node)
{
    if (node == NULL) {
        goto out;
    }

    ASSERT("valid ref", node->ref != 0);

    node->ref--;
    if (node->ref == 0) {
        hudnode_release_above_below(node);
        if (node->f_stream) {
            streamnode_free(node);
        } else {
            hudnode_free(node);
        }
    }

out:
    return NULL;
}

/*
 * This function safely release a previous reference while assigning a new one
 * into the supplied np pointer.  Use this function instead of hudnode_addref
 * or hudnode_release calls, as it guarantees proper behavior and idempotence
 * regardless of the incoming value of 'node'.
 */
void
hudnode_swapref(struct hudnode **np, struct hudnode *node)
{
    struct hudnode *tmp = *np;
    *np = hudnode_addref(node);
    hudnode_release(tmp);
}

/*
 * Bind the supplied flow with the chain indicated by the filter.
 */
void
hudnode_flow_connect(struct connflow *cf, struct hudnode *node)
{
    struct hudnode *f_top;
    struct hudnode *f_bot;

    hudnode_printf("NODE", uflow_fromconnflow(cf),
            "pre-%s: %p", __func__, node);

    if (node == NULL) {
        goto out;
    }

    f_top = node->f_top ? node : NULL;
    f_bot = node->f_bottom ? node : NULL;

    if (node->f_top && !node->f_bottom) {
        while (!node->f_bottom) {
            node = HUDNODE_NEXT(node, below);
        }
        f_bot = node;
    } else if (!node->f_top && node->f_bottom) {
        while (!node->f_top) {
            node = HUDNODE_NEXT(node, above);
        }
        f_top = node;
    }

    ASSERT("unbalanced", (cf->bottom_node == NULL) == (cf->top_node == NULL));

    if (((cf->bottom_node != NULL) && HUDNODE_IS_ACTIVE(cf->bottom_node)) ||
            ((cf->top_node != NULL) && HUDNODE_IS_ACTIVE(cf->top_node))) {
        hudnode_clear_chain(cf);
    }

    hudnode_swapref(&cf->bottom_node, f_bot);
    hudnode_swapref(&cf->top_node, f_top);

out:
    hudnode_printf("NODE", uflow_fromconnflow(cf), "post-%s", __func__);
}

/*
 * Replace the filter's static node with one newly allocated.
 */
struct hudnode *
hudnode_prime(struct connflow *cf, struct hudnode *node,
        struct hudnode *caller)
{
    struct hudfilter *filter = HUDNODE_FILTER(node);
    struct hudfilter_base *this = &filter->base;
    struct hudnode *ins = NULL;

    ASSERT("inactive", !HUDNODE_IS_ACTIVE(node));

    ASSERT("bottom filter", !node->f_bottom ||
            (HUDNODE_FILTER(cf->bottom_node) == filter));
    ASSERT("duplicate priming", !node->f_bottom ||
            !HUDNODE_IS_ACTIVE(cf->bottom_node));

    ASSERT("top filter", !node->f_top ||
            (HUDNODE_FILTER(cf->top_node) == filter));
    ASSERT("duplicate priming", !node->f_top ||
            !HUDNODE_IS_ACTIVE(cf->top_node));

    ins = hudnode_alloc(cf, node, this->pcb_sz);
    if (ins == NULL) {
        /* XXX Need an error log here. */
        goto out;
    }
    ins->ref = 1;

    hudnode_printf("NODE", uflow_fromconnflow(cf), "%p->%p - %s - prime",
            node, ins, this->name);

    /* Insert it into the chain. */
    hudnode_swap(cf, caller, node, ins);

    ASSERT("swaped in", ins->ref > 1);

    ins->ref--;

    hudnode_printf("NODE", uflow_fromconnflow(cf), "%s - primed", this->name);

out:
    return ins;
}

/*
 * Worlds most complicated swap function, due to all the various requirements.
 */
void
hudnode_swap(struct connflow *cf, struct hudnode *caller, struct hudnode *node,
        struct hudnode *ins)
{
    struct hudnode *old_node;

    if (ins == NULL) {
        hudnode_remove(uflow_fromconnflow(cf), node);
        goto out;
    }

    /* Same node; no-op. */ 
    if (ins == node) {
        goto out;
    }

    /* Take a reference to prevent mid-swap deallocation. */
    old_node = hudnode_addref(node);

    /*
     * Swapping two non-instantiated nodes, so basic chain
     * manipulation in progress.
     */
    if (!HUDNODE_IS_ACTIVE(node) && !HUDNODE_IS_ACTIVE(ins)) {
        /*
         * Don't allow a inactive node already wired into another chain to be
         * inserted into this one; things just get confusing.
         */
        ASSERT("available node", ins->ref == 1);
        ASSERT("no up", ins->above == NULL);
        ASSERT("no down", ins->below == NULL);

        /*
         * If a connflow was passed in here, then things are probably
         * incorrectly configured, since a static hudnode list isn't supposed
         * to be modified at runtime within a flow.
         */
        ASSERT("no cf", cf == NULL);

        hudnode_swapref(&ins->below, node->below);
        if (ins->below != NULL) {
            hudnode_swapref(&ins->below->above, ins);
        }
        hudnode_swapref(&node->below, NULL);

        hudnode_swapref(&ins->above, node->above);
        if (ins->above != NULL) {
            hudnode_swapref(&ins->above->below, ins);
        }
        hudnode_swapref(&node->above, NULL);
        goto done;
    }

    /*
     * Totally defensive validation check, make sure the node being replaced
     * is actually in a chain.  Ugliest ASSERT macro ever.
     */
    ASSERT("connected node",
        ((node->below == NULL)
            ? ((node->above == NULL)
                ? (cf->bottom_node == node && cf->top_node == node)
                : ((!HUDNODE_IS_ACTIVE(node->above) || (node->above->below == node)) && (cf->bottom_node == node)))
            : ((node->above == NULL)
                ? ((!HUDNODE_IS_ACTIVE(node->below) || (node->below->above == node)) && (cf->top_node == node))
                : ((node->above->below == node) || (node->below->above == node)))));

    /*
     * When building out a new node, the caller node must be supplied so that
     * there is an edge to attach the new node to.  Since the static node
     * never gets linked with active nodes, there's no way to go from the
     * 'node' to the other actives.
     */
    if (!HUDNODE_IS_ACTIVE(node) && HUDNODE_IS_ACTIVE(ins)) {
        /* Replace an inactive node with a newly instantiated one. */
        if (caller == NULL) {
            /* Replace an inactive edge node, or possibly the only node. */
            ASSERT("edge node", (node->below == NULL) || (node->above == NULL));
            if (node->below == NULL) {
                hudnode_swapref(&ins->above, node->above);
                hudnode_swapref(&ins->below, NULL);
                hudnode_swapref(&cf->bottom_node, ins);
            }
            if (node->above == NULL) {
                hudnode_swapref(&ins->below, node->below);
                hudnode_swapref(&ins->above, NULL);
                hudnode_swapref(&cf->top_node, ins);
            } 
        } else {
            /* Building a chain out. */
            ASSERT("instantiated caller", HUDNODE_IS_ACTIVE(caller));
            ASSERT("caller correct", (caller->above == node) ||
                    (caller->below == node));
            if (caller->above == node) {
                hudnode_swapref(&ins->below, caller);
                hudnode_swapref(&caller->above, ins);
                hudnode_swapref(&ins->above, node->above);
                if (node->above == NULL) {
                    hudnode_swapref(&cf->top_node, ins);
                } else {
                    ASSERT("edge node", !HUDNODE_IS_ACTIVE(node->above));
                }
            } else {
                ASSERT("edge node", !HUDNODE_IS_ACTIVE(node->below));
                hudnode_swapref(&ins->above, caller);
                hudnode_swapref(&caller->below, ins);
                hudnode_swapref(&ins->below, node->below);
                if (node->below == NULL) {
                    hudnode_swapref(&cf->bottom_node, ins);
                } else {
                    ASSERT("edge node", !HUDNODE_IS_ACTIVE(node->below));
                }
            }
        }
        goto done;
    }

    /*
     * In the future, this clause will likely have to be modified slightly to
     * allow for an instantiated node to be replaced by a static one from a
     * different filter.  For now, this is not supported.
     */
    if (HUDNODE_IS_ACTIVE(node) && !HUDNODE_IS_ACTIVE(ins)) {
        BOOL below_valid = FALSE;
        ASSERT("valid uninst", &HUDNODE_FILTER(node)->node == ins);
        if (node->below == NULL) {
            /*
             * Either there's only one node in the chain, or the other end is
             * still active.
             */
            ASSERT("bottom node", cf->bottom_node == node);
            if (node->above == NULL) {
                ASSERT("unorphaned chain", cf->top_node == node);
            } else {
                ASSERT("unorphaned chain", !HUDNODE_IS_ACTIVE(node->above) ||
                        HUDNODE_IS_ACTIVE(cf->top_node));
            }
            hudnode_swapref(&cf->bottom_node, ins);
            below_valid = TRUE;
        } else {
            if (HUDNODE_IS_ACTIVE(node->below)) {
                hudnode_swapref(&node->below->above, ins);
                hudnode_swapref(&node->below, NULL);
            } else {
                /*
                 * It might be legal to replace an instantiated node with an
                 * entirely new filter node.  In the mean time, replace it
                 * first with it's uninstantiated node, and then do a second
                 * swap operation.
                 */
                ASSERT("valid chain", node->below->above == ins);
                hudnode_swapref(&node->below, NULL);
                below_valid = TRUE;
            }
        }

        if (node->above == NULL) {
            /*
             * Either there's only one node in the chain, or the other end is
             * still active.
             */
            ASSERT("top node", cf->top_node == node);
            if (node->below == NULL) {
                ASSERT("unorphaned chain", below_valid || cf->bottom_node == node);
            } else {
                ASSERT("unorphaned chain", !HUDNODE_IS_ACTIVE(node->below) ||
                        HUDNODE_IS_ACTIVE(cf->bottom_node));
            }
            hudnode_swapref(&cf->top_node, ins);
        } else {
            if (HUDNODE_IS_ACTIVE(node->above)) {
                hudnode_swapref(&node->above->below, ins);
                hudnode_swapref(&node->above, NULL);
            } else {
                /*
                 * It might be legal to replace an instantiated node with an
                 * entirely new filter node.  In the mean time, replace it
                 * first with it's uninstantiated node, and then do a second
                 * swap operation.
                 */
                ASSERT("valid chain", node->above->below== ins);
                hudnode_swapref(&node->above, NULL);
            }
        }
        goto done;
    }

    /*
     * Replacing two active nodes is almost the simplest step.
     */
    if (HUDNODE_IS_ACTIVE(node) && HUDNODE_IS_ACTIVE(ins)) {
        /*
         * This assertion is purely defensive at the moment, and should go
         * away once more dynamic hudchain behaviors are supported.
         */
        ASSERT("coherent filter chain", node->private == ins->private);
        if (node->below == NULL) {
            hudnode_swapref(&cf->bottom_node, ins);
            hudnode_swapref(&ins->below, NULL);
        } else {
            hudnode_swapref(&ins->below, node->below);
            if (HUDNODE_IS_ACTIVE(ins->below)) {
                hudnode_swapref(&ins->below->above, ins);
            }
            hudnode_swapref(&node->below, NULL);
        }

        if (node->above == NULL) {
            hudnode_swapref(&cf->top_node, ins);
            hudnode_swapref(&ins->above, NULL);
        } else {
            hudnode_swapref(&ins->above, node->above);
            if (HUDNODE_IS_ACTIVE(node->above)) {
                hudnode_swapref(&node->above->below, ins);
            }
            hudnode_swapref(&node->above, NULL);
        }
        goto done;
    }

done:
    hudnode_release(old_node);

out:
    ;
}

/*
 * Insert a single node immediately above a supplied node.
 */
void
hudnode_insert(struct hudnode *node, struct hudnode *ins)
{
    struct hudnode *next;

    ASSERT("active nodes", HUDNODE_IS_ACTIVE(HUDNODE_NEXT(node, above)) ==
            HUDNODE_IS_ACTIVE(node));
    next = hudnode_addref(HUDNODE_NEXT(node, above));
    hudnode_swapref(&node->above, ins);
    hudnode_swapref(&ins->below, node);
    hudnode_swapref(&next->below, ins);
    hudnode_swapref(&ins->above, next);
    hudnode_release(next);
}

/*
 * Remove a single specified node from the uflow.  Must be an ACTIVE node,
 * or uf must be NULL.
 */
void
hudnode_remove(union uflow *uf, struct hudnode *node)
{
    /*
     * If 'node' is the bottom node, and is being removed, then it may fail
     * the assert check during the top_node handling that protects against
     * orphaned segments of the graph.  Track this with the bottom_node
     * boolean.
     */
    BOOL bottom_node = FALSE;
    struct hudnode *old_node = hudnode_addref(node);

    ASSERT("active node", (uf != NULL) == HUDNODE_IS_ACTIVE(node));

    if (uf == NULL) {
        /*
         * Proxy chains don't support removing the top or bottom from this
         * interface.
         */
        ASSERT("middle node", (node->above != NULL) &&
            (node->below != NULL));
        hudnode_swapref(&node->below->above, node->above);
        hudnode_swapref(&node->above->below, node->below);
        goto out;
    }

    /* First, look below... */
    if (node->below == NULL) {
        /* Adjust the connflow. */
        ASSERT("valid cf", uflow_bottom_node(uf) == node);
        bottom_node = TRUE;     /* Prereq: the above assert passes. */
        hudnode_swapref(uflow_ptr_bottom_node(uf), node->above);
    } else {
        if (HUDNODE_IS_ACTIVE(node->below)) {
            hudnode_swapref(&node->below->above, node->above);
        } else {
            /*
             * Validation check to protect against active hudnodes being
             * orphaned in the middle of a chain.
             */
            ASSERT("unorphaned chain", HUDNODE_IS_ACTIVE(uflow_top_node(uf)));
        }
    }

    /* Then, look above. */
    if (node->above == NULL) {
        /* Adjust the connflow's top_node pointer. */
        ASSERT("valid uf", uflow_top_node(uf) == node);
        hudnode_swapref(uflow_ptr_top_node(uf), node->below);
    } else {
        if (HUDNODE_IS_ACTIVE(node->above)) {
            hudnode_swapref(&node->above->below, node->below);
        } else {
            /*
             * Validation check to protect against active hudnodes being
             * orphaned in the middle of a chain.
             */
            ASSERT("unorphaned chain", bottom_node ||
                    HUDNODE_IS_ACTIVE(uflow_bottom_node(uf)));
        }
    }

out:
    /*
     * Replace the node above and below with a node that ignores all
     * messages and ingress/egress data.
     */
    hudnode_remove_above_below(node);

    /* Drop early-deallocation-preventing reference. */
    hudnode_release(old_node);
}

/*
 * Utility function to fully populate a chain; should be removed in subsequent
 * impelementations as the hudnode approach extends throughout the system.
 */
err_t
hudnode_build_chain(struct connflow *cf, struct hudnode *node,
        BOOL from_below)
{
    struct hudnode *caller = NULL;
    err_t err = ERR_OK;

    for (; node != NULL; node = from_below ? HUDNODE_NEXT(node, above) :
            HUDNODE_NEXT(node, below))
    {
        if (node->f_no_prime) {
            /*
             * "f_no_prime" is not meant to be used by bottom or top nodes so
             * "caller" must be non-NULL here.
             */
            if (from_below) {
                hudnode_swapref(&caller->above, node->above);
            } else {
                hudnode_swapref(&caller->below, node->below);
            }
            continue;
        }

        caller = hudnode_prime(cf, node, caller);
        if (caller == NULL) {
            /*
             * Can safely clear the chain because no node has yet received a
             * FLOW_INIT, ergo there is no need to queue a ABORT.
             */
            hudnode_clear_chain(cf);
            err = ERR_MEM;
            break;
        }

    }

    hudnode_printf("NODE", uflow_fromconnflow(cf), "built chain");

    return err;
}

/*
 * Destroy an entire chain and returns it to static hudnodes.
 */
void
hudnode_clear_chain(struct connflow *cf)
{
    struct hudfilter *f_bottom = NULL;
    struct hudfilter *f_top = NULL;
    struct hudproxy *proxy;

    if ((cf->bottom_node == NULL) || (cf->top_node == NULL)) {
        ASSERT("balanced nodes", (cf->bottom_node == NULL) ==
                (cf->top_node == NULL));
        goto out;
    }

    hudnode_printf("NODE", uflow_fromconnflow(cf), "freeing chain");
    /* Save the non-active nodes for the chain. */
    f_bottom = HUDNODE_FILTER(cf->bottom_node);
    f_top = HUDNODE_FILTER(cf->top_node);

    /*
     * Add a ref to the proxy to stop f_bottom and f_top being free'd should
     * this be the last node to use the proxy.
     */
    proxy = f_bottom->base.proxy;
    if (proxy != NULL) {
        hudproxy_addref(proxy);
    }

    /* Remove all active nodes from each end. */
    while ((cf->bottom_node != NULL) && HUDNODE_IS_ACTIVE(cf->bottom_node)) {
        hudnode_remove(uflow_fromconnflow(cf), cf->bottom_node);
    }

    while ((cf->top_node != NULL) && HUDNODE_IS_ACTIVE(cf->top_node)) {
        hudnode_remove(uflow_fromconnflow(cf), cf->top_node);
    }

    hudnode_swapref(&cf->bottom_node, &f_bottom->node);
    hudnode_swapref(&cf->top_node, &f_top->node);

    if (proxy != NULL) {
        hudproxy_release(proxy);
    }

    hudnode_printf("NODE", uflow_fromconnflow(cf), "chain freed");

out:
    return;
}

/*
 * Find the previous node to this current inactive filter/node.  Since this
 * could be an active node that doesn't have a backlink, in this
 * implementation we have to walk the chain to find the forward link into this
 * node.  Plenty of optimization opportunities here, but this code should go
 * away in future versions when the 'caller' is passed in as a common
 * parameter.
 */
struct hudnode *
hudnode_prev_node(struct connflow *cf, struct hudnode *orig_node,
        BOOL from_below, BOOL *found)
{
    struct hudfilter *filter = HUDNODE_FILTER(orig_node);
    struct hudnode *node = from_below ? cf->bottom_node : cf->top_node;
    struct hudfilter *f = HUDNODE_FILTER(node);
    struct hudnode *prev_node = NULL;

    for (; (f != NULL) && (f != filter); f = HUDNODE_FILTER(node)) {
        prev_node = node;
        node = from_below ? HUDNODE_NEXT(node, above) :
                HUDNODE_NEXT(node, below);
        if (node == NULL) {
            /* Filter not found. */
            break;
        }
    }

    if (prev_node != NULL) {
        ASSERT("valid node", HUDNODE_IS_ACTIVE(prev_node));
    }

    if (f == filter) *found = TRUE;

    return prev_node;
}

/*
 * printf the hudnode chain for this connflow.
 */
#define HUDNODE_SZ_DBG_BUF 360
static RTTHREAD char hudnode_dbg_buffer[HUDNODE_SZ_DBG_BUF];

void
hudnode_dump(union uflow *uf)
{
    hudnode_print(uflow_bottom_node(uf), uflow_top_node(uf));
}

void
hudnode_print(struct hudnode *bottom_node, struct hudnode *top_node)
{
    struct hudnode *node = bottom_node;
    const char *name;
    int i;
    int p = 0;
    BOOL cur_active;
    char *buffer = hudnode_dbg_buffer;
    const SIZE sz_buf = HUDNODE_SZ_DBG_BUF;

    if ((bottom_node == NULL) && (top_node == NULL)) {
        printf("<empty>");
        return;
    }

    if ((bottom_node != NULL) && (top_node != NULL) &&
            HUDNODE_IS_ACTIVE(bottom_node) &&
            HUDNODE_IS_ACTIVE(top_node))
    {
        /* Simple hudchain with everything active. */
        while (node != NULL) {
            name = HUDNODE_NAME(node);
            for (i = 0; name[i] != '\0'; i++) {
                buffer[p++] = tolower(name[i]);
                if (p >= sz_buf) {
                    goto overflow;
                }
            }
            buffer[p++] = '0' + node->ref;
            if (HUDNODE_CTX(node) != NULL) {
                buffer[p++] = '*';
            }
            if (node->above != NULL) {
                if (p + 5 >= sz_buf) {
                    goto overflow;
                }
                sprintf(buffer + p, " <-> ");
                p += 5;
            }
            node = node->f_top ? NULL : node->above;
        }
        buffer[p] = '\0';
        printf("%s", buffer);
        goto out;
    }

    if (top_node == NULL || !HUDNODE_IS_ACTIVE(top_node)) {
        cur_active = HUDNODE_IS_ACTIVE(bottom_node);
        while (node != NULL) {
            if (!HUDNODE_IS_ACTIVE(node)) {
                cur_active = FALSE;
            }
            name = HUDNODE_NAME(node);
            for (i = 0; name[i] != '\0'; i++) {
                buffer[p++] = cur_active ? tolower(name[i]) :
                    toupper(name[i]);
                if (p >= sz_buf) {
                    goto overflow;
                }
            }
            buffer[p++] = '0' + node->ref;
            if (HUDNODE_CTX(node) != NULL) {
                buffer[p++] = '*';
            }
            if (node->above != NULL) {
                if (p + 5 >= sz_buf) {
                    goto overflow;
                }
                if (cur_active && !HUDNODE_IS_ACTIVE(node->above)) {
                    sprintf(buffer + p, " --> ");
                } else if (cur_active) {
                    sprintf(buffer + p, " <-> ");
                } else if (!cur_active) {
                    sprintf(buffer + p, " <=> ");
                }
                p += 5;
            }
            node = node->f_top ? NULL : node->above;
        }
        if (p == sz_buf) {
            goto overflow;
        }
        buffer[p] = '\0';
        printf("%s", buffer);
        goto out;
    }

    if (((bottom_node == NULL) || !HUDNODE_IS_ACTIVE(bottom_node)) &&
            HUDNODE_IS_ACTIVE(top_node)) {
        p = sz_buf - 2;
        buffer[sz_buf - 1] = '\0';

        cur_active = HUDNODE_IS_ACTIVE(bottom_node);
        while (node != NULL) {
            if (!HUDNODE_IS_ACTIVE(node)) {
                cur_active = FALSE;
            }
            name = HUDNODE_NAME(node);
            for (i = strlen(name) - 1; i >= 0; i--) {
                buffer[p--] = cur_active ? tolower(name[i]) :
                    toupper(name[i]);
                if (p == 0) {
                    goto underflow;
                }
            }
            buffer[p--] = '0' + node->ref;
            if (HUDNODE_CTX(node) != NULL) {
                buffer[p--] = '*';
            }
            if (node->below != NULL) {
                if (p == 5) {
                    goto underflow;
                }
                if (cur_active && !HUDNODE_IS_ACTIVE(node->below)) {
                    memcpy(buffer + p - 5, " <-- ", 5);
                } else if (cur_active) {
                    memcpy(buffer + p - 5, " <-> ", 5);
                } else if (!cur_active) {
                    memcpy(buffer + p - 5, " <=> ", 5);
                }
                p -= 5;
            }
            node = node->f_bottom ? NULL : node->below;
        }
        printf("%s", buffer + p + 1);
        goto out;
    }
out:
    return;

overflow:
    buffer[sz_buf - 2] = '%';
    buffer[sz_buf - 1] = '\0';
    printf("%s", buffer);
    return;

underflow:
    buffer[0] = '%';
    printf("%s", buffer);
}

struct connflow *
hud_get_flow(struct hudnode *hn)
{
    struct connflow   *cf = NULL;
    struct method_data md;
    struct hudvariant  result;

    if (hn != NULL) {
        md.typeid   = NULL;
        md.methodid = HUDNODE_METHOD_GET_FLOW;
        md.argc     = 0;
        md.argv     = NULL;
        md.result   = &result;
        hudvariant_init(&result);

        hud_handle_default(hn, HUDCTL_PERFORM_METHOD, NULL, &md);
        if (!hudvariant_is_error(&result)) {
            cf = hudvariant_get_ptr(&result);
        }
        hudvariant_uninit(&result);
    }
    return cf;
}

