#define ERR(err, out)                                                      \
    do {                                                                   \
        if ((err) != ERR_OK) {                                             \
            goto out;                                                      \
        }                                                                  \
    } while (0)
#define NULL_CHECK(ptr, err, val, out)                                     \
    do {                                                                   \
        if ((ptr) == NULL) {                                               \
            (err) = (val);                                                 \
            goto out;                                                      \
        }                                                                  \
    } while (0)

struct aimcp_sessionid_parts {
    struct mr_refstring *pool_name;
    struct mr_refstring *mcp_session_id;
    ip_tuple_t ip_tup;
    SSIZE addr_size;
};

struct aimcp_header {
    BYTE *buf;
    SIZE len;
};

struct aimcp_scb {
    struct tmm_aes_key *tmm_aes_key;
    struct tmm_aes_key *tmm_aes_key_irule;
    struct aimcp_sessionid_parts parsed;
    struct aimcp_header saved_sid;
    union uflow *uf;
};

struct aimcp_pcb {
    struct aimcp_scb scb;
};

struct aimcp_cfg {
    BYTE *passphrase;
    SIZE passphrase_len;
    struct profile_listener *pl;
    struct tmm_profile_aimcp_stat *stats;
};

const static struct aimcp_cfg aimcp_default_cfg = {
        .passphrase = NULL,
        .passphrase_len = 0,
};

static err_t
aimcp_header_construct(struct aimcp_header *hdr, const SIZE len)
{
    err_t err = ERR_OK;
    BYTE *alloc_buf;

    NULL_CHECK(hdr, err, ERR_ARG, out);

    alloc_buf = umalloc(len, M_FILTER, 0);
    NULL_CHECK(alloc_buf, err, ERR_MEM, out);
    hdr->buf = alloc_buf;
    hdr->len = len;

out:
    return err;
}

static void
aimcp_header_destruct(struct aimcp_header *hdr)
{
    if (hdr != NULL) {
        ufree(hdr->buf);
        hdr->buf = NULL;
        hdr->len = 0;
    }
}

