/*
 * The intent of this code is to surround the interface to a filter.
 * The inputs and outputs (messages and payload) will be buffered
 * when necessary to ensure that ordering between the two is
 * maintained.
 *
 * If a buffer grows too large, then flow-control will be used to
 * communicate with adjacent filters.  The inner filter will be
 * isolated from flow-control concerns.  In particular:
 * 1) Ingress does not need to be completely absorbed.  Extra ingress
 * will be buffered within the orbit.
 * 2) There is no distinction between hud and hudQ functions.  The orbit
 * will automatically chose the right one based on the current state.
 * 3) There is no need to handle XOFF and SENT events.  When a filter is
 * ready to see more messages and payload, the hud_orbit_unpause()
 * function shoud be used.
 * 4) If either ingress or egress is ignorable for the filter, then the
 * hud_orbit_set_passthru-*() functions may be used to allow the orbit
 * infrastructure to completely bypass the filter for the unwanted
 * direction.
 *
 * The orbit's state is stored in a block of memory allocated before the
 * hudnode for a filter.  The filter can use the normal hudnode API for
 * all other usage.  (The orbit can calculate the offset from the
 * hudnode pointer to obtain the struct hud_orbit state.)
 *
 * Orbits will override the filter's handler functions on a hudnode to
 * point to the orbit handler.  External filters will thus call into
 * orbit functions when delivering messages to the wrapped filter.
 *
 * A tunable 'msg_size' is available to support message-only protocols.
 * This represents the effective overhead a message may have.
 * 8192 / msg_size messages may be buffered before flow-control kicks in.
 */

#define ORB_WATERMARK               8192

/* This will queue up to 512 messages by default */
#define ORB_DEFAULT_MESSAGE_SIZE    16

#define ORB_POOL_SIZE    16

#define ORB_DEBUG 0

#if ORB_DEBUG

#define ORB_TRACEF(o, f, fmt, ...) do {                                     \
    if ((f) == NULL) {                                                      \
        printf("[%p %s][%-25.25s] " fmt "\n", (o), HUDNODE_NAME(&o->node),  \
                __func__, ##__VA_ARGS__);                                   \
    } else {                                                                \
        const struct connflow *_cf;                                         \
        const struct streamflow *_sf;                                       \
        if (const_uflow_expand((f), &_cf, &_sf) == uflow_type_connflow) {   \
            printf("[%p %s][%-25.25s] %p [%c]" fmt "\n", (o),               \
                HUDNODE_NAME(&o->node), __func__, (f),                      \
                uflow_is_clientside(f) ? 'C' : 'S', ##__VA_ARGS__);         \
        } else {                                                            \
            printf("[%p %s][%-25.25s] %p [%c:%d]" fmt "\n", (o),            \
                HUDNODE_NAME(&o->node), __func__, (f),                      \
                uflow_is_clientside(f) ? 'C' : 'S',                         \
                _sf->stream_id, ##__VA_ARGS__);                             \
        }                                                                   \
    }                                                                       \
} while(/*CONSTCOND*/0)
#else
#define ORB_TRACEF(o, f, fmt, ...)                      /* Nothing. */
#endif

struct hud_orb_entry {
    /*
     * The xb.xfrag_head.tqh_last field is used to determine whether
     * or not this entry is a message or an xbuf. An xbuf will have
     * a non-NULL value, and message will have this field be NULL.
     *
     * The struct xbuf field must be first, to match the cast in
     * hud_orbit_entry_xb().
     */
    struct xbuf xb;
    SIMPLEQ_ENTRY(hud_orb_entry) next;
};

enum orb_flags {
    ORB_F_INGRESS,
    ORB_F_INGRESS_OUT,
    ORB_F_EGRESS,
    ORB_F_EGRESS_OUT,
    ORB_F_REMOVED
};

struct hud_orbit {
    /* The queue */
    struct hud_orb_queue queue;

    stream_handler handler;
    stream_processor ingress_handler;
    stream_processor egress_handler;

    UINT32 ingress_len;
    UINT32 egress_len;

    UINT32 high_watermark;
    UINT32 low_watermark;

    UINT32 message_size;

    /* The hud_orbit_internal_flag_#() functions depend on this being last */
    UINT32 flags;

    struct hudnode node;
};

#define ORB_FLAG_TEST(O, F) (!!((O)->flags & (F)))
#define ORB_FLAG_SET(O, F) ((O)->flags |= (F))
#define ORB_FLAG_UNSET(O, F) ((O)->flags &= ~(F))
#define ORB_FLAG_TOGGLE(O, F) ((O)->flags ^= (F))

/* Make sure an orbit is a multiple of the cacheline size */
STATIC_ASSERT((HUD_ORBIT_SIZE & (CACHE_ALIGN - 1)) == 0);
STATIC_ASSERT(sizeof(struct hud_orbit) ==
        (HUD_ORBIT_SIZE + sizeof(struct hudnode)));

/*
 * Hack - Use a string constant to determine whether or not a
 * HUDEVT_CALLBACK is for us or not.
 */
static void hud_orbit_trim_cache(void);
static const char * const orb_callback = "hudorbit";
static GLOBALSET umem_handle_t hud_orb_entry_cache;
static GLOBALSET struct umem_create hud_orb_entry_cache_create = {
    .name           = "hud_orbit_entry",
    .size           = sizeof(struct hud_orb_entry),
    .handle         = &hud_orb_entry_cache,
    .trim           = hud_orbit_trim_cache
};
DATA_SET(umem_create_set, hud_orb_entry_cache_create);

static RTTHREAD struct hud_orb_entry *hud_orbit_entry_pool[ORB_POOL_SIZE];
static RTTHREAD int hud_orbit_entry_pool_count;

/* Predeclarations */
static err_t hud_orbit_process_ingress_fastpath(struct hudnode *node,
        union uflow *uf, struct xbuf *xb);
static err_t hud_orbit_process_egress_fastpath(struct hudnode *node,
        union uflow *uf, struct xbuf *xb);
static void hud_orbit_handler_fastpath(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data);
static err_t hud_orbit_process_ingress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb);
static err_t hud_orbit_process_egress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb);
static void hud_orbit_handler(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data);

/* Current state of "node | direction" */
RTTHREAD UINT64 hud_orbit_state;

/*
 * Queue library functions
 */

/* Print a queue to stdout.  Useful for debugging */
void
hud_orbit_print_queue(struct hud_orb_queue *q)
{
    hud_msg_t msg;
    void *data;
    struct hud_orb_entry *entry;

    SIMPLEQ_FOREACH(entry, q, next) {
        if (hud_orbit_entry_is_xb_raw(entry)) {
            printf("Queue %u entry %p xbuf length %u\n",
                    hud_orbit_entry_flags_get(entry),
                    entry, hud_orbit_entry_xb(entry)->len);
        } else {
            hud_orbit_entry_msg(entry, &msg, &data);
            printf("Queue %u entry %p msg %s %p\n",
                    hud_orbit_entry_flags_get(entry),
                    entry, hud_msg_name_str(msg), data);
        }
    }
}

struct hud_orb_entry *
hud_orbit_pop_queue(struct hud_orb_queue *q)
{
    struct hud_orb_entry *entry = SIMPLEQ_FIRST(q);
    if (entry != NULL) {
        /* Pop the entry */
        SIMPLEQ_REMOVE_HEAD(q, entry, next);
    }

    return entry;
}

/* Get the entry at the start of the queue */
struct hud_orb_entry *
hud_orbit_queue_head(struct hud_orb_queue *q)
{
    return SIMPLEQ_FIRST(q);
}

void
hud_orbit_free_msg_data(hud_msg_t msg, void *data)
{
    /* XXX This will break with a HTTP2 PUSH, perhaps? */
    if ((msg == HUDEVT_MESSAGE) || (msg == HUDCTL_MESSAGE) ||
        (msg == HUDEVT_META) || (msg == HUDCTL_META)) {
        hud_ref_release(data);
    }
    if (((msg == HUDEVT_MESSAGE_DONE) || (msg == HUDCTL_MESSAGE_DONE)) &&
            (data != NULL)) {
        /* XXX Assumption: Only UDP and Websockets should hit this */
        hud_ref_release(data);
    }
}

void
hud_orbit_free_entry(struct hud_orb_entry *entry)
{
    if (hud_orbit_entry_pool_count == ORB_POOL_SIZE) {
        umem_cache_free_n(hud_orb_entry_cache, ORB_POOL_SIZE / 2,
                (void **) &hud_orbit_entry_pool[ORB_POOL_SIZE / 2]);
        hud_orbit_entry_pool_count = ORB_POOL_SIZE / 2;
    }

    hud_orbit_entry_pool[hud_orbit_entry_pool_count] = entry;
    hud_orbit_entry_pool_count++;
}

static void
hud_orbit_trim_cache(void)
{
    umem_cache_free_n(hud_orb_entry_cache, hud_orbit_entry_pool_count,
                (void **)hud_orbit_entry_pool);
    hud_orbit_entry_pool_count = 0;
}

void
hud_orbit_free_entry_contents(struct hud_orb_entry *entry)
{
    if (entry != NULL) {
        if (hud_orbit_entry_is_xb_raw(entry)) {
            xbuf_free(&entry->xb);
        } else {
            hud_orbit_free_msg_data(entry->xb.mss,
                    entry->xb.xfrag_head.tqh_first);
        }
    }
}

/* Insert an entry at the start of the queue */
void
hud_orbit_queue_insert_head_entry(struct hud_orb_queue *q,
        struct hud_orb_entry *entry)
{
    SIMPLEQ_INSERT_HEAD(q, entry, next);
}

/* Insert an entry at the end of the queue */
void
hud_orbit_queue_insert_tail_entry(struct hud_orb_queue *q,
        struct hud_orb_entry *entry)
{
    SIMPLEQ_INSERT_TAIL(q, entry, next);
}

/* Insert an entry after another one */
void
hud_orbit_queue_insert_after_entry(struct hud_orb_queue *q,
        struct hud_orb_entry *cursor, struct hud_orb_entry *entry)
{
    SIMPLEQ_INSERT_AFTER(q, cursor, entry, next);
}

/* Puts the contents of q2 after q1 in q1. */
void
hud_orbit_splice(struct hud_orb_queue *q1, struct hud_orb_queue *q2)
{
    SIMPLEQ_SPLICE(q1, q2);
}

static inline struct hud_orb_entry *
hud_orbit_alloc_entry(void)
{
    struct hud_orb_entry *entry;
    if (hud_orbit_entry_pool_count == 0) {
        hud_orbit_entry_pool_count = umem_cache_alloc_n(hud_orb_entry_cache,
                0, ORB_POOL_SIZE / 2, (void **)hud_orbit_entry_pool);
    }

    if (hud_orbit_entry_pool_count != 0) {
        hud_orbit_entry_pool_count--;
        entry = hud_orbit_entry_pool[hud_orbit_entry_pool_count];
    } else {
        entry = NULL;
    }
    return entry;
}

struct hud_orb_entry *
hud_orbit_create_entry_msg(hud_msg_t msg, void *data, UINT32 extra, UINT8 flags)
{
    struct hud_orb_entry *entry = hud_orbit_alloc_entry();
    if (unlikely(entry == NULL)) {
        hud_orbit_free_msg_data(msg, data);
    } else {
        entry->xb.len = extra;
        hud_orbit_entry_flags_set(entry, flags);
        entry->xb.mss = msg;
        entry->xb.xfrag_head.tqh_first = data;
        entry->xb.xfrag_head.tqh_last = NULL;
    }

    return entry;
}

struct hud_orb_entry *
hud_orbit_create_entry_xb(struct xbuf *xb, UINT8 flags)
{
    struct hud_orb_entry *entry = hud_orbit_alloc_entry();
    if (likely(entry != NULL)) {
        xbuf_embed_init(&entry->xb, xb->mss);
        xbuf_merge(&entry->xb, xb);

        /* Overwrite flags */
        hud_orbit_entry_flags_set(entry, flags);
    } else {
        xbuf_free(xb);
    }

    return entry;
}

struct hud_orb_entry *
hud_orbit_create_entry_empty(UINT16 mss, UINT8 flags)
{
    struct hud_orb_entry *entry = hud_orbit_alloc_entry();
    if (entry != NULL) {
        xbuf_embed_init(&entry->xb, mss);

        /* Overwrite flags */
        hud_orbit_entry_flags_set(entry, flags);
    }

    return entry;
}

/* If the first entry in the queue is an xbuf, return a pointer to it */
struct xbuf *
hud_orbit_queue_head_xb(struct hud_orb_queue *q)
{
    struct hud_orb_entry *entry = SIMPLEQ_FIRST(q);
    struct xbuf *xb = NULL;
    if (hud_orbit_entry_is_xb(entry)) {
        xb = &entry->xb;
    }

    return xb;
}

/* If the last entry in the queue is an xbuf, return a pointer to it */
struct xbuf *
hud_orbit_queue_tail_xb(struct hud_orb_queue *q)
{
    struct hud_orb_entry *entry;
    struct xbuf *xb = NULL;

    if (!SIMPLEQ_EMPTY(q)) {
        entry = containerof(struct hud_orb_entry, next, q->sqh_last);
        if (hud_orbit_entry_is_xb_raw(entry)) {
            xb = &entry->xb;
        }
    }

    return xb;
}

/* If the first entry in the queue is an xbuf, return a pointer to it */
struct xbuf *
hud_orbit_queue_head_xb_match(struct hud_orb_queue *q, UINT8 flags)
{
    struct hud_orb_entry *entry = SIMPLEQ_FIRST(q);
    struct xbuf *xb = NULL;
    if (hud_orbit_entry_is_xb(entry) &&
            (hud_orbit_entry_flags_get(entry) == flags)) {
        xb = &entry->xb;
    }

    return xb;
}

/* If the last entry in the queue is an xbuf, return a pointer to it */
struct xbuf *
hud_orbit_queue_tail_xb_match(struct hud_orb_queue *q, UINT8 flags)
{
    struct hud_orb_entry *entry;
    struct xbuf *xb = NULL;
    if (!SIMPLEQ_EMPTY(q)) {
        entry = containerof(struct hud_orb_entry, next, q->sqh_last);
        if (hud_orbit_entry_is_xb_raw(entry) &&
                (hud_orbit_entry_flags_get(entry) == flags)) {
            xb = &entry->xb;
        }
    }

    return xb;
}

/*
 * Orbit library functions
 */

/* Get the orbit for a hudnode */
static inline struct hud_orbit *
HUDNODE_ORBIT(struct hudnode *node)
{
    return containerof(struct hud_orbit, node, node);
}

void
hud_orbit_set_msg_size(struct hudnode *node, UINT32 size)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    INSIST("Initialization must happen in FLOW_INIT",
            hud_orbit_state & ORB_STATE_INIT);
    orb->message_size = size;
}

BOOL
hud_orbit_ingress_is_blocked(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    return ORB_FLAG_TEST(orb, ORB_FG_EXISTS_INGRESS_OUT);
}

BOOL
hud_orbit_egress_is_blocked(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    return ORB_FLAG_TEST(orb, ORB_FG_BLOCKED_DOWN);
}

static void
hud_orbit_trigger_flush(struct hud_orbit *orb, union uflow *uf)
{
    if (!ORB_FLAG_TEST(orb, ORB_FG_CALLBACK)) {
        ORB_FLAG_SET(orb, ORB_FG_CALLBACK);
        uflowQ_handle(&orb->node, HUDEVT_CALLBACK, uf, (void *) orb_callback);
    }
}

static void
hud_orbit_check_ingress_fastpath(struct hud_orbit *orb)
{
    /* See if we can toggle to the fastpath */
    if (!ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS | ORB_FG_PASSTHRU_UP |
            ORB_FG_PAUSE_INGRESS | ORB_FG_EXISTS_INGRESS | ORB_FG_PACKET)) {
        orb->node.s_ingress = hud_orbit_process_ingress_fastpath;
    }
}

static void
hud_orbit_check_egress_fastpath(struct hud_orbit *orb)
{
    /* See if we can toggle to the fastpath */
    if (!ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_PASSTHRU_DOWN |
            ORB_FG_PAUSE_EGRESS | ORB_FG_BLOCKED_DOWN | ORB_FG_EXISTS_EGRESS |
            ORB_FG_PACKET) &&
            (orb->egress_len <= orb->high_watermark)) {
        orb->node.s_egress = hud_orbit_process_egress_fastpath;
    }
}

static void hud_orbit_check_handler_fastpath(struct hud_orbit *orb)
{
    if (!ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_PASSTHRU_DOWN |
            ORB_FG_PAUSE_EGRESS | ORB_FG_EXISTS_EGRESS |
            ORB_FG_DROP_INGRESS | ORB_FG_PASSTHRU_UP | ORB_FG_PAUSE_INGRESS |
            ORB_FG_EXISTS_INGRESS)) {
        hudnode_set_handler(&orb->node, hud_orbit_handler_fastpath);
    }
}

void
hud_orbit_set_passthru_ingress(struct hudnode *node, union uflow *uf, BOOL val)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct hud_orb_entry *entry;
    struct hud_orb_queue ingress_out_queue;
    struct hud_orb_queue tmp_queue;

    if (ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_UP) != val) {
        ORB_FLAG_TOGGLE(orb, ORB_FG_PASSTHRU_UP);
        if (val) {
            orb->node.s_ingress = hud_orbit_process_ingress;
            hudnode_set_handler(&orb->node, hud_orbit_handler);
            ORB_FLAG_UNSET(orb, ORB_FG_PAUSE_INGRESS);

            SIMPLEQ_INIT(&ingress_out_queue);
            SIMPLEQ_INIT(&tmp_queue);
            ORB_FLAG_SET(orb, ORB_FG_QUEUE_ALTERED);

            /* Pull out all ingress entries into a different queue */
            while ((entry = SIMPLEQ_FIRST(&orb->queue)) != NULL) {
                SIMPLEQ_REMOVE_HEAD(&orb->queue, entry, next);
                if (hud_orbit_entry_flags_get(entry) == ORB_F_INGRESS) {
                    hud_orbit_entry_flags_set(entry, ORB_F_INGRESS_OUT);
                    SIMPLEQ_INSERT_TAIL(&ingress_out_queue, entry, next);
                } else {
                    SIMPLEQ_INSERT_TAIL(&tmp_queue, entry, next);
                }
            }

            /* Fix up the queue existence flags */
            if (!SIMPLEQ_EMPTY(&ingress_out_queue)) {
                ORB_FLAG_SET(orb, ORB_FG_EXISTS_INGRESS_OUT);
            }
            ORB_FLAG_UNSET(orb, ORB_FG_EXISTS_INGRESS);

            /* Put them at the end of the queue in correct relative order */
            SIMPLEQ_SPLICE(&orb->queue, &tmp_queue);
            SIMPLEQ_SPLICE(&orb->queue, &ingress_out_queue);

            /* Flush when safe */
            hud_orbit_trigger_flush(orb, uf);
        } else {
            hud_orbit_check_ingress_fastpath(orb);
            hud_orbit_check_handler_fastpath(orb);
        }
    }
}

static void
hud_orbit_aborted(struct hud_orbit *orb, union uflow *uf, const char *msg)
{
    ORB_FLAG_SET(orb, ORB_FG_DROP_EGRESS);
    ORB_FLAG_SET(orb, ORB_FG_DROP_INGRESS);

    /* Switch out of the fastpath */
    if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
        orb->node.s_ingress = hud_orbit_process_ingress;
        orb->node.s_egress = hud_orbit_process_egress;
    }
    hudnode_set_handler(&orb->node, hud_orbit_handler);

    uflowQ_handle(&orb->node, HUDEVT_ABORTED, uf, RST_WHY(uf, msg));
}

void
hud_orbit_set_passthru_egress(struct hudnode *node, union uflow *uf, BOOL val)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct hud_orb_entry *entry;
    struct hud_orb_queue egress_out_queue;
    struct hud_orb_queue tmp_queue;

    if (ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_DOWN) != val) {
        ORB_FLAG_TOGGLE(orb, ORB_FG_PASSTHRU_DOWN);
        if (val) {
            node->s_egress = hud_orbit_process_egress;
            hudnode_set_handler(node, hud_orbit_handler);
            ORB_FLAG_UNSET(orb, ORB_FG_PAUSE_EGRESS);

            SIMPLEQ_INIT(&egress_out_queue);
            SIMPLEQ_INIT(&tmp_queue);
            ORB_FLAG_SET(orb, ORB_FG_QUEUE_ALTERED);

            /* Pull out all egress entries into a different queue */
            while ((entry = SIMPLEQ_FIRST(&orb->queue)) != NULL) {
                SIMPLEQ_REMOVE_HEAD(&orb->queue, entry, next);
                if (hud_orbit_entry_flags_get(entry) == ORB_F_EGRESS) {
                    hud_orbit_entry_flags_set(entry, ORB_F_EGRESS_OUT);
                    SIMPLEQ_INSERT_TAIL(&egress_out_queue, entry, next);
                } else {
                    SIMPLEQ_INSERT_TAIL(&tmp_queue, entry, next);
                }
            }

            /* Fix up the queue existence flags */
            if (!SIMPLEQ_EMPTY(&egress_out_queue)) {
                ORB_FLAG_SET(orb, ORB_FG_EXISTS_EGRESS_OUT);
            }
            ORB_FLAG_UNSET(orb, ORB_FG_EXISTS_EGRESS);

            /* Put them at the end of the queue in correct relative order */
            SIMPLEQ_SPLICE(&orb->queue, &tmp_queue);
            SIMPLEQ_SPLICE(&orb->queue, &egress_out_queue);

            /* Flush when safe */
            hud_orbit_trigger_flush(orb, uf);
        } else {
            hud_orbit_check_egress_fastpath(orb);
            hud_orbit_check_handler_fastpath(orb);
        }
    }
}

static void
hud_orbit_enqueue_xb(struct hud_orbit *orb, union uflow *uf, struct xbuf *xb,
        enum orb_flags flag)
{
    struct xbuf *xb_dest;
    struct hud_orb_entry *entry;

    /* Don't queue an empty buffer */
    if (unlikely(xb->len == 0)) {
        goto out;
    }

    /* We have been freed already */
    if (ORB_FLAG_TEST(orb, ORB_FG_FREE)) {
        xbuf_free(xb);
        goto out;
    }

    /* Can we append to an existing buffer? */
    xb_dest = hud_orbit_queue_tail_xb_match(&orb->queue, flag);
    if (xb_dest != NULL) {
        struct xfrag *xfdest, *next;

        xfdest = xfrag_check(TAILQ_FIRST(&xb_dest->xfrag_head));
        next = xfrag_check(TAILQ_NEXT(xfdest, xfrag_entry));

        /*
         * Allow one runt xfrag at the head of the xbuf to minimize copying.
         */
        if (next != NULL) {
            xbuf_merge_compact(xb_dest, xb);
        } else {
            xbuf_merge(xb_dest, xb);
        }
        goto out;
    }

    entry = hud_orbit_create_entry_xb(xb, flag);
    if (entry == NULL) {
        hud_orbit_aborted(orb, uf, "Out of memory queuing data");
    } else {
        hud_orbit_queue_insert_tail_entry(&orb->queue, entry);
        ORB_FLAG_SET(orb, ORB_FG_EXISTS_INGRESS << flag);
        hudnode_set_handler(&orb->node, hud_orbit_handler);
    }

out:
    return;
}

static void
hud_orbit_enqueue_msg(struct hud_orbit *orb, hud_msg_t msg, union uflow *uf,
        void *data, enum orb_flags flag)
{
    struct hud_orb_entry *entry;

    if (ORB_FLAG_TEST(orb, ORB_FG_FREE)) {
        /* Message seen after getting a HUDCTL_ABORT */
        hud_orbit_free_msg_data(msg, data);
        goto out;
    }

    entry = hud_orbit_create_entry_msg(msg, data, 0, flag);
    if (entry == NULL) {
        hud_orbit_aborted(orb, uf,  "Out of memory queuing a message");
    } else {
        hud_orbit_queue_insert_tail_entry(&orb->queue, entry);
        ORB_FLAG_SET(orb, ORB_FG_EXISTS_INGRESS << flag);
        hudnode_set_handler(&orb->node, hud_orbit_handler);
    }

out:
    return;
}

static void
hud_orbit_apply_ingress_flow_control(struct hud_orbit *orb, union uflow *uf)
{
    if ((ORB_FLAG_TEST(orb, ORB_FG_XOFF_ABOVE) ||
            (orb->ingress_len > orb->high_watermark)) !=
                    ORB_FLAG_TEST(orb, ORB_FG_XOFF_BELOW)) {
        ORB_FLAG_TOGGLE(orb, ORB_FG_XOFF_BELOW);
        if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_NOTIFY_XOFF))) {
            /* Inform it directly */
            orb->handler(&orb->node, HUDCTL_XOFF, uf,
                PTR(ORB_FLAG_TEST(orb, ORB_FG_XOFF_BELOW)));
        } else {
            uflow_handle_lower(&orb->node, HUDCTL_XOFF, uf,
                PTR(ORB_FLAG_TEST(orb, ORB_FG_XOFF_BELOW)));
        }
    }
}

/*
 * hud_orbit_report_mu_delta - update egress_len and conditionally report a
 * MU delta to the proxy.
 *
 * Sets orb->egress_len to @new_egress_len, computing the old MU count from
 * the current orb->egress_len before overwriting it.  A report is sent only
 * when uf is non-NULL, and the integer number of 8 KiB units changes (delta != 0).
 *
 * Both intermediate (non-top) orbits and top-node orbits (orbitized
 * hudproxies buffering their own egress on behalf of a blocked peer) report
 * their buffered memory units.  For a top node the report is dispatched to
 * the proxy itself via uflow_proxy_handle(), so the proxy accounts the egress
 * buffers it holds the same way it accounts deltas reported by the hudnodes
 * stacked above it.
 */
static void
hud_orbit_report_mu_delta(struct hud_orbit *orb, union uflow *uf,
        UINT32 new_egress_len)
{
    UINT32 old_mu;
    UINT32 new_mu;
    INT32  delta;
    struct method_data md;
    struct hudvariant argv[1];
    struct hudvariant result;

    old_mu = orb->egress_len / ORB_MU_SIZE;
    orb->egress_len = new_egress_len;

    /* MU reporting only supported on clientside currently. */
    if ((uf == NULL) || IS_SERVERSIDE(uflow_get_connflow(uf))) {
        goto out;
    }

    new_mu = new_egress_len / ORB_MU_SIZE;

    /* Report only on 8 KiB boundary crossings */
    delta = (INT32)new_mu - (INT32)old_mu;
    if (delta == 0) {
        goto out;
    }

    hudvariant_init(&result);
    hudvariant_init(&argv[0]);
    hudvariant_set_int(&argv[0], (UINT32)delta);

    md.typeid   = &hudfilter_proxy_typeid;
    md.methodid = HUDPROXY_METHOD_REPORT_MEMORY_DELTA;
    md.argc     = 1;
    md.argv     = argv;
    md.result   = &result;

    uflow_proxy_handle(HUDCTL_PERFORM_METHOD, uf, &md);
out:
    return;
}

static void
hud_orbit_apply_egress_flow_control(struct hud_orbit *orb, union uflow *uf)
{
    union uflow *peer;

    if (orb->egress_len <= orb->high_watermark) {
        goto out;
    }
    if (HUDNODE_IS_TOP(&orb->node)) {
        if (ORB_FLAG_TEST(orb, ORB_FG_PEER_XOFF)) {
            goto out;
        }
        ORB_FLAG_SET(orb, ORB_FG_PEER_XOFF);
        peer = uflow_peer(uf);
        if ((peer != NULL) &&
                ha_active_unit(uflow_get_connflow(uf)->ha_unit)) {
            uflow_proxy_handle(HUDCTL_XOFF, peer, (void *)TRUE);
        }
        goto out;
    }
    if (!ORB_FLAG_TEST(orb, ORB_FG_SENT)) {
        ORB_FLAG_SET(orb, ORB_FG_SENT);
        ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
        uflow_handle_upper(&orb->node, HUDEVT_PAUSE_EGRESS, uf, (void *)TRUE);
    }

out:
    return;
}

static void
hud_orbit_flush(struct hud_orbit *orb, union uflow *uf)
{
    struct hud_orb_entry *entry, *prepend, *prepend_scan, *next;
    struct hud_orb_entry **prev;
    union uflow *peer;
    struct xbuf *xb;
    hud_msg_t msg;
    void *data;
    enum orb_flags flags;
    BOOL trigger_callback = FALSE;
    BOOL accepted;
    UINT32 exists = 0, skip = 0;
    UINT32 exists_mask = ORB_FG_EXISTS_INGRESS | ORB_FG_EXISTS_INGRESS_OUT |
                ORB_FG_EXISTS_EGRESS | ORB_FG_EXISTS_EGRESS_OUT;
    UINT32 pause = orb->flags &
        (ORB_FG_PAUSE_INGRESS | ORB_FG_PAUSE_INGRESS_OUT |
        ORB_FG_PAUSE_EGRESS | ORB_FG_PAUSE_EGRESS_OUT);

    if (ORB_FLAG_TEST(orb, ORB_FG_FLUSHING | ORB_FG_CALLBACK)) {
        goto out;
    }
    ORB_FLAG_SET(orb, ORB_FG_FLUSHING);
    ORB_FLAG_UNSET(orb, ORB_FG_QUEUE_ALTERED);

    prev = &orb->queue.sqh_first;
    entry = SIMPLEQ_FIRST(&orb->queue);

    if (ORB_FLAG_TEST(orb, ORB_FG_HAIRPIN) &&
            (orb->egress_len > orb->high_watermark)) {
        /* Do not release ingress to filter while egress congested. */
        skip |= 1 << ORB_F_INGRESS;
    }

    /* Scan the queue */
    while ((entry != NULL) && (exists != (orb->flags & exists_mask))) {
        if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_QUEUE_ALTERED))) {
            /*
             * Stop scanning if the queue was altered.
             * Our knowledge of what was scanned is wrong.
             * Assume all sub-queues have entries, and let
             * a later flush sort it out.
             */
            trigger_callback = TRUE;
            exists = exists_mask;
            break;
        }

        /* Get the sub-queue */
        flags = hud_orbit_entry_flags_get(entry);

        /* This sub-queue has no entries above, and not paused? */
        if ((exists & (ORB_FG_EXISTS_INGRESS << flags)) ||
                ORB_FLAG_TEST(orb, ORB_FG_PAUSE_INGRESS << flags)) {
            goto ignore;
        }

        /* Skip this queue? */
        if (skip & (1 << flags)) {
            goto ignore;
        }

        /* Logically remove the entry by changing the flags */
        hud_orbit_entry_flags_set(entry, ORB_F_REMOVED);

        /* Remember the start of the queue, to know if entries are added */
        prepend = SIMPLEQ_FIRST(&orb->queue);

        switch (flags) {
        case ORB_F_EGRESS_OUT:
            if (ORB_FLAG_TEST(orb, ORB_FG_BLOCKED_DOWN)) {
                /* Can't send down right now */
                break;
            }

            if (hud_orbit_state_mismatch(&orb->node, ORB_STATE_DOWN)) {
                /* Direction means we can't handle this yet */
                trigger_callback = TRUE;
                break;
            }

            if (!hud_orbit_entry_is_xb(entry)) {
                hud_orbit_report_mu_delta(orb, uf,
                        orb->egress_len - orb->message_size);
                hud_orbit_entry_msg(entry, &msg, &data);
                uflow_handle_lower(&orb->node, msg, uf, data);
                goto remove;
            }

            xb = hud_orbit_entry_xb(entry);
            hud_orbit_report_mu_delta(orb, uf, orb->egress_len - xb->len);
            uflow_process_lower(&orb->node, uf, xb);
            if (likely(xb->len == 0)) {
                goto remove;
            }

            /*
             * The peer rejected part of the xbuf; restore the remaining
             * bytes.  This is the moment TMM starts holding data on behalf
             * of a blocked peer.
             */
            ORB_FLAG_SET(orb, ORB_FG_BLOCKED_DOWN);
            hud_orbit_report_mu_delta(orb, uf, orb->egress_len + xb->len);
            ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u",
                    xb->len, orb->egress_len);
            break;

        case ORB_F_INGRESS_OUT:
            if (hud_orbit_state_mismatch(&orb->node, ORB_STATE_UP)) {
                /* Direction means we can't handle this yet */
                trigger_callback = TRUE;
                break;
            }

            accepted = FALSE;
            if (ORB_FLAG_TEST(orb, ORB_FG_ACCEPTED)) {
                ORB_FLAG_UNSET(orb, ORB_FG_ACCEPTED);
                ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
                accepted = TRUE;
            }
            if (hud_orbit_entry_is_xb(entry)) {
                if (accepted) {
                    uflow_handle_upper(&orb->node, HUDEVT_ACCEPTED, uf, NULL);
                }
                xb = hud_orbit_entry_xb(entry);
                orb->ingress_len -= xb->len;
                uflow_process_upper(&orb->node, uf, xb);
                xbuf_free(xb);
            } else {
                orb->ingress_len -= orb->message_size;
                hud_orbit_entry_msg(entry, &msg, &data);
                if (accepted && (msg != HUDEVT_EOF) && (msg != HUDEVT_SHUTDOWN) &&
                        (msg != HUDEVT_INGRESS_ABORT)) {
                    uflow_handle_upper(&orb->node, HUDEVT_ACCEPTED, uf, NULL);
                }
                uflow_handle_upper(&orb->node, msg, uf, data);
            }
            goto remove;

        case ORB_F_EGRESS:
            if (!hud_orbit_entry_is_xb(entry)) {
                hud_orbit_entry_msg(entry, &msg, &data);
                orb->handler(&orb->node, msg, uf, data);
                hud_orbit_report_mu_delta(orb, uf, orb->egress_len - orb->message_size);
                goto remove;
            }
            xb = hud_orbit_entry_xb(entry);
            hud_orbit_report_mu_delta(orb, uf, orb->egress_len - xb->len);
            orb->egress_handler(&orb->node, uf, xb);
            if (likely(xb->len == 0)) {
                goto remove;
            }
            hud_orbit_report_mu_delta(orb, uf, orb->egress_len + xb->len);
            ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u",
                    xb->len, orb->egress_len);
            ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS);
            break;

        case ORB_F_INGRESS:
            if (!hud_orbit_entry_is_xb(entry)) {
                hud_orbit_entry_msg(entry, &msg, &data);
                orb->handler(&orb->node, msg, uf, data);
                orb->ingress_len -= orb->message_size;
                goto remove;
            }
            xb = hud_orbit_entry_xb(entry);
            orb->ingress_len -= xb->len;
            orb->ingress_handler(&orb->node, uf, xb);
            if (likely(xb->len == 0)) {
                goto remove;
            }
            orb->ingress_len += xb->len;
            ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u",
                    xb->len, orb->ingress_len);
            ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS);
            break;
        case ORB_F_REMOVED:
            break;
        }

        /* Scan pushed back entries */
        if (!ORB_FLAG_TEST(orb, ORB_FG_QUEUE_ALTERED)) {
            prepend_scan = SIMPLEQ_FIRST(&orb->queue);
            while (prepend_scan != prepend) {
                /* Notice, and add to the subqueue */
                exists |= ORB_FG_EXISTS_INGRESS <<
                        hud_orbit_entry_flags_get(prepend_scan);

                /* Update the previous pointer if required */
                if (SIMPLEQ_NEXT(prepend_scan, next) == entry) {
                    prev = &SIMPLEQ_NEXT(prepend_scan, next);
                }
                prepend_scan = SIMPLEQ_NEXT(prepend_scan, next);
            }
        }

        /* Restore the flags to put the entry back */
        hud_orbit_entry_flags_set(entry, flags);

ignore:
        /* Ignore this entry */
        prev = &SIMPLEQ_NEXT(entry, next);
        entry = SIMPLEQ_NEXT(entry, next);

        /* Remember this sub-queue has entries */
        exists |= (ORB_FG_EXISTS_INGRESS << flags);
        continue;

remove:
        /* Scan pushed back entries */
        if (!ORB_FLAG_TEST(orb, ORB_FG_QUEUE_ALTERED)) {
            prepend_scan = SIMPLEQ_FIRST(&orb->queue);
            while (prepend_scan != prepend) {
                /* Notice, and add to the subqueue */
                exists |= ORB_FG_EXISTS_INGRESS <<
                        hud_orbit_entry_flags_get(prepend_scan);

                /* Update the previous pointer if required */
                if (SIMPLEQ_NEXT(prepend_scan, next) == entry) {
                    prev = &SIMPLEQ_NEXT(prepend_scan, next);
                }
                prepend_scan = SIMPLEQ_NEXT(prepend_scan, next);
            }
        }

        /*
         * In rare situations, the queue has been rearranged.
         * See i.e. hud_orbit_set_passthru_egress().
         * In which case, the previous pointer is out of date.
         * Scan to find it.
         */
        if (unlikely(*prev != entry)) {
            prev = &SIMPLEQ_FIRST(&orb->queue);
            while (*prev != entry) {
                prev = &SIMPLEQ_NEXT(*prev, next);
            }
        }

        /* Remove the entry */
        next = SIMPLEQ_NEXT(entry, next);
        *prev = next;
        if (*prev == NULL) {
            orb->queue.sqh_last = prev;
        }
        hud_orbit_free_entry(entry);
        entry = next;
    }

    /* Which of the four queues still have entries? */
    orb->flags &= ~exists_mask;
    orb->flags |= exists;

    /* Has enough ingress been drained? */
    hud_orbit_apply_ingress_flow_control(orb, uf);

    /* Was ingress skipped and sufficient egress been drained? */
    if (skip && (1 << ORB_F_INGRESS) &&
            ORB_FLAG_TEST(orb, ORB_FG_HAIRPIN) &&
                (orb->egress_len < orb->low_watermark)) {
        /* Yes, attempt to flush ingress. */
        trigger_callback = TRUE;
    }

    /* Should now release HUDEVT_ACCEPTED? */
    if (unlikely((orb->flags & (ORB_FG_ACCEPTED | ORB_FG_HOLD_ACCEPTED)) ==
            ORB_FG_ACCEPTED)) {
        ORB_FLAG_UNSET(orb, ORB_FG_ACCEPTED);
        ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
        uflow_handle_upper(&orb->node, HUDEVT_ACCEPTED, uf, NULL);
    }

    /* A callback is already pending */
    if (ORB_FLAG_TEST(orb, ORB_FG_CALLBACK)) {
        goto done;
    }

    /*
     * We may not have been allowed to flush the outgoing queues due to
     * direction constraints.  If so, queue a callback to trigger this
     * from within a nicer context.
     */
    if (trigger_callback) {
        goto trigger_callback;
    }

    if ((ORB_FLAG_TEST(orb, ORB_FG_SENT | ORB_FG_PEER_XOFF)) &&
            !ORB_FLAG_TEST(orb, ORB_FG_PAUSE_EGRESS) &&
            (orb->egress_len < orb->low_watermark)) {
        if (hud_orbit_state_mismatch(&orb->node, ORB_STATE_UP)) {
            goto trigger_callback;
        }
        if (ORB_FLAG_TEST(orb, ORB_FG_PEER_XOFF)) {
            ORB_FLAG_UNSET(orb, ORB_FG_PEER_XOFF);
            peer = uflow_peer(uf);
            if (peer != NULL) {
                uflow_proxy_handle(HUDCTL_XOFF, peer, NULL);
            }
        } else {
            /* Send HUDEVT_SENT after draining all egress data. */
            if (!ORB_FLAG_TEST(orb, ORB_FG_BLOCKED_DOWN)) {
                ORB_FLAG_UNSET(orb, ORB_FG_SENT);
                if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_NOTIFY_SENT))) {
                    /* Inform it directly */
                    orb->handler(&orb->node, HUDEVT_SENT, uf, NULL);
                } else {
                    uflowQ_handle_upper(&orb->node, HUDEVT_SENT, uf, NULL);
                }
            }
        }
    }

    /*
     * If we were once paused, but now unpaused, then we can
     * still have flushable entries so try to flush again.
     */
    if ((pause & ~orb->flags) && !SIMPLEQ_EMPTY(&orb->queue)) {
        goto trigger_callback;
    }

    /* Do we need to remove this node? */
    if (!ORB_FLAG_TEST(orb, ORB_FG_COMPLETE) ||
            ORB_FLAG_TEST(orb, ORB_FG_ACCEPTED | ORB_FG_FREE |
                    ORB_FG_BLOCKED_DOWN)) {
        /* Have we drained enough to switch to the fast paths? */
        hud_orbit_check_ingress_fastpath(orb);
        hud_orbit_check_egress_fastpath(orb);
        hud_orbit_check_handler_fastpath(orb);

        /*
         * Not trying to remove this node, waiting to flush ACCEPTED
         * and/or rejected EGRESS, or already dead.
         */
        goto done;
    }

    tmmrule_reset_node(&orb->node, uf);

    /* Are there any pending hudQ messages to this node? */
    if (hud_abort_node_safe(&orb->node)) {
        /* Can remove this node now */
        ORB_FLAG_UNSET(orb, ORB_FG_FLUSHING);
        hud_abort_node(uf, &orb->node);

        /* Cannot touch orb after this point */
        goto out;
    }

    /* Trigger another callback to get into the right state to drain more */
trigger_callback:
    ORB_FLAG_SET(orb, ORB_FG_CALLBACK);
    uflowQ_handle(&orb->node, HUDEVT_CALLBACK, uf, (void *) orb_callback);

done:
    ORB_FLAG_UNSET(orb, ORB_FG_FLUSHING);
out:
    return;
}

static void
hud_orbit_handler(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    UINT64 orig_state, state = INT(node);

    ORB_TRACEF(orb, uf, "%s", hud_msg_name_str(msg));

    switch (msg) {
    case HUDEVT_FLOW_INIT:
        /* Reset flags as previous state is gone */
        orb->flags = 0;
        orb->ingress_len = 0;
        orb->egress_len = 0;
        hud_orbit_report_mu_delta(orb, uf, 0);
        node->s_ingress = hud_orbit_process_ingress_fastpath;
        if (!HUDNODE_IS_TOP(node)) {
            node->s_egress = hud_orbit_process_egress_fastpath;
        }
        hud_orbit_check_handler_fastpath(orb);
        state += ORB_STATE_UP | ORB_STATE_INIT;
        break;

    case HUDEVT_ACCEPTED:
        if (ORB_FLAG_TEST(orb, ORB_FG_HOLD_ACCEPTED)) {
            ORB_FLAG_SET(orb, ORB_FG_ACCEPTED);
            goto out;
        }
        /* Fall through */

    case HUDEVT_ABORTED:
    case HUDEVT_EXPIRED:
        state += ORB_STATE_UP;
        break;

    case HUDEVT_COMPRESS:
    case HUDEVT_CRYPTO:
    case HUDEVT_DECOMPRESS:
    case HUDEVT_RESOLVED:
    case HUDEVT_TCL:
    case HUDEVT_TCL_CHILD:
    case HUDEVT_TIMER:
    case HUDEVT_CMP_PERSIST_REPLY:
        state += ORB_STATE_UP | ORB_STATE_DOWN;
        break;

    case HUDCTL_ABORT:
    case HUDCTL_TEARDOWN:
        state += ORB_STATE_DOWN;
        break;

        /* Synchronous messages of a specific direction */
    case HUDCTL_CONNECT:
    case HUDCTL_OOB:
    case HUDCTL_SYNACK:
    case HUDCTL_URGENT:
        state += ORB_STATE_DOWN;
        break;

    case HUDEVT_OOB:
    case HUDEVT_SYN:
    case HUDEVT_SYNACK:
        state += ORB_STATE_UP;
        break;

    case HUDCTL_XOFF:
        if (ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_UP) &&
                !ORB_FLAG_TEST(orb, ORB_FG_EXISTS_INGRESS_OUT)) {
            uflow_handle_lower(node, msg, uf, data);
            goto out;
        }
        if (data != NULL) {
            if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_XOFF_ABOVE))) {
                goto out;
            }
            ORB_FLAG_SET(orb, ORB_FG_XOFF_ABOVE);
        } else {
            ORB_FLAG_UNSET(orb, ORB_FG_XOFF_ABOVE);
        }
        hud_orbit_apply_ingress_flow_control(orb, uf);
        goto out;

    case HUDEVT_PAUSE_EGRESS:
        if (ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_DOWN) &&
                !ORB_FLAG_TEST(orb, ORB_FG_EXISTS_EGRESS_OUT)) {
            uflow_handle_upper(node, msg, uf, data);
            goto out;
        }
        if (data != NULL) {
            ORB_FLAG_SET(orb, ORB_FG_BLOCKED_DOWN);
            goto out;
        }

        /* Fall through.  data == NULL acts like HUDEVT_SENT */
    case HUDEVT_SENT:
        ORB_FLAG_UNSET(orb, ORB_FG_BLOCKED_DOWN);
        if (ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_DOWN) &&
                !ORB_FLAG_TEST(orb, ORB_FG_EXISTS_EGRESS_OUT)) {
            ORB_FLAG_UNSET(orb, ORB_FG_INSERT);

            if (ORB_FLAG_TEST(orb, ORB_FG_COMPLETE) &&
                    !ORB_FLAG_TEST(orb, ORB_FG_EXISTS_INGRESS_OUT)) {
                /* Flush to finally remove complete node. */
                hud_orbit_trigger_flush(orb, uf);
            }

            uflow_handle_upper(node, msg, uf, data);
            goto out;
        }

        /*
         * There is communication with filter above, so no need to
         * forward SENT.  We'll send it when we drain the egress queue.
         */
        if (ORB_FLAG_TEST(orb, ORB_FG_EXISTS_EGRESS)) {
            ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
        }

        /*
         * Make sure to forward a HUDEVT_SENT if it might not be for us.
         * This can happen if we are inserted into a chain that has
         * already had flow-control occurring on it.
         */
        if (ORB_FLAG_TEST(orb, ORB_FG_INSERT) &&
                !ORB_FLAG_TEST(orb, ORB_FG_ACCEPTED)) {
            ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
            ORB_FLAG_SET(orb, ORB_FG_SENT);
        }

        if (ORB_FLAG_TEST(orb, ORB_FG_NOTIFY_SENT)) {
            ORB_FLAG_SET(orb, ORB_FG_SENT);
        }

        /* SENT is weird in that it allows data to go down */
        orig_state = hud_orbit_state;
        hud_orbit_state = state + ORB_STATE_DOWN;
        hud_orbit_flush(orb, uf);
        hud_orbit_state = orig_state;
        goto out;

    case HUDEVT_CALLBACK:
        if (data != orb_callback) {
            state += ORB_STATE_UP | ORB_STATE_DOWN;
            break;
        }

        /* This one is for us */
        ORB_FLAG_UNSET(orb, ORB_FG_CALLBACK);

        if (ORB_FLAG_TEST(orb, ORB_FG_FREE)) {
            /* Already freed all pending messages */
            goto out;
        }

        /* Trigger flushing */
        orig_state = hud_orbit_state;
        hud_orbit_state = state + (ORB_STATE_UP | ORB_STATE_DOWN);
        hud_orbit_flush(orb, uf);
        hud_orbit_state = orig_state;
        goto out;

    case HUDCTL_INGRESS_STOP:
        ORB_FLAG_SET(orb, ORB_FG_DROP_INGRESS);
        /* Switch out of the fastpath */
        if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
            orb->node.s_ingress = hud_orbit_process_ingress;
            hudnode_set_handler(&orb->node, hud_orbit_handler);
        }
        break;

    case HUDEVT_EGRESS_STOP:
        ORB_FLAG_SET(orb, ORB_FG_DROP_EGRESS);
        /* Switch out of the fastpath */
        if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
            orb->node.s_egress = hud_orbit_process_egress;
            hudnode_set_handler(&orb->node, hud_orbit_handler);
        }
        break;

    /*
     * Asynchronous HUDCTLs
     */
    case HUDCTL_EGRESS_ABORT:
    case HUDCTL_MESSAGE:
    case HUDCTL_MESSAGE_DONE:
    case HUDCTL_META:
    case HUDCTL_REQUEST:
    case HUDCTL_REQUEST_DONE:
    case HUDCTL_RESPONSE:
    case HUDCTL_RESPONSE_DONE:
    case HUDCTL_RESPONSE_WITH_REQUEST:
    case HUDCTL_RESPONSE_WITH_REQUEST_DONE:
    case HUDCTL_SHUTDOWN:
        /*
         * If we are aborting, silently absorb all messages until the
         * HUDCTL_ABORT arrives
         */
        if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS))) {
            hud_orbit_free_msg_data(msg, data);
            goto out;
        }

        if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_DOWN))) {
            orig_state = hud_orbit_state;
            hud_orbit_state = state + ORB_STATE_DOWN;
            hud_orbit_handle_lower(node, msg, uf, data);
            hud_orbit_state = orig_state;
            goto out;
        }

        /* Enqueue if the queue is not empty, or we are paused. */
        if (unlikely(ORB_FLAG_TEST(orb,
                ORB_FG_PAUSE_EGRESS | ORB_FG_EXISTS_EGRESS))) {
            hud_orbit_enqueue_msg(orb, msg, uf, data, ORB_F_EGRESS);
            hud_orbit_report_mu_delta(orb, uf, orb->egress_len + orb->message_size);
            if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
                orb->node.s_egress = hud_orbit_process_egress;
            }

            hud_orbit_apply_egress_flow_control(orb, uf);
            goto out;
        }

        state += ORB_STATE_DOWN;
        break;

    /*
     * Asynchronous HUDEVTs
     */
    case HUDEVT_MESSAGE:
    case HUDEVT_MESSAGE_DONE:
    case HUDEVT_META:
    case HUDEVT_REQUEST:
    case HUDEVT_REQUEST_DONE:
    case HUDEVT_RESPONSE:
    case HUDEVT_RESPONSE_DONE:
    case HUDEVT_RESPONSE_WITH_REQUEST:
    case HUDEVT_RESPONSE_WITH_REQUEST_DONE:
    case HUDEVT_USER_EOM:
    case HUDEVT_USER_REQUEST:
    case HUDEVT_USER_RESPONSE:
        /*
         * If we are aborting, silently absorb all messages until the
         * HUDCTL_ABORT arrives
         */
        if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS))) {
            hud_orbit_free_msg_data(msg, data);
            goto out;
        }

        /* Fall through */
    case HUDEVT_EOF:
    case HUDEVT_SHUTDOWN:
    case HUDEVT_CLOSED:
    case HUDEVT_CONNECTED:
    case HUDEVT_INGRESS_ABORT:

        if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_UP))) {
            orig_state = hud_orbit_state;
            hud_orbit_state = state + ORB_STATE_UP;
            hud_orbit_handle_upper(node, msg, uf, data);
            hud_orbit_state = orig_state;
            goto out;
        }

        /* Enqueue if the queue is not empty, or we are paused. */
        if (unlikely(ORB_FLAG_TEST(orb,
                ORB_FG_PAUSE_INGRESS | ORB_FG_EXISTS_INGRESS))) {
            hud_orbit_enqueue_msg(orb, msg, uf, data, ORB_F_INGRESS);
            orb->ingress_len += orb->message_size;
            if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
                orb->node.s_ingress = hud_orbit_process_ingress;
            }

            /* Attempt to turn off ingress if we have too much */
            hud_orbit_apply_ingress_flow_control(orb, uf);
            goto out;
        }

        state += ORB_STATE_UP;
        break;

    /*
     * Syncronous messages
     * Queue our output due to unknown state of the caller
     */
    default:
        break;
    }

    /* Otherwise, deliver immediately */
    orig_state = hud_orbit_state;
    hud_orbit_state = state;
    orb->handler(node, msg, uf, data);
    hud_orbit_state = orig_state;

out:
    return;
}

static const UINT8 hud_orbit_msg_state[HUDEVT_LAST] =
{
    /* Synchronous controls */
    [HUDCTL_ABORT] = ORB_STATE_SLOW,
    [HUDCTL_CONNECT] = ORB_STATE_DOWN,
    [HUDCTL_INGRESS_STOP] = ORB_STATE_SLOW,
    [HUDCTL_TEARDOWN] = ORB_STATE_SLOW,
    [HUDCTL_URGENT] = ORB_STATE_DOWN,
    [HUDCTL_XOFF] = ORB_STATE_SLOW,

    /* Non-global controls */
    [HUDCTL_OOB] = ORB_STATE_DOWN,
    [HUDCTL_SYNACK] = ORB_STATE_DOWN,

    /* Asynchronous controls */
    [HUDCTL_EGRESS_ABORT] = ORB_STATE_DOWN,
    [HUDCTL_MESSAGE] = ORB_STATE_DOWN,
    [HUDCTL_MESSAGE_DONE] = ORB_STATE_DOWN,
    [HUDCTL_META] = ORB_STATE_DOWN,
    [HUDCTL_REQUEST] = ORB_STATE_DOWN,
    [HUDCTL_REQUEST_DONE] = ORB_STATE_DOWN,
    [HUDCTL_RESPONSE] = ORB_STATE_DOWN,
    [HUDCTL_RESPONSE_DONE] = ORB_STATE_DOWN,
    [HUDCTL_RESPONSE_WITH_REQUEST] = ORB_STATE_DOWN,
    [HUDCTL_RESPONSE_WITH_REQUEST_DONE] = ORB_STATE_DOWN,
    [HUDCTL_SHUTDOWN] = ORB_STATE_DOWN,

    /* Events */
    [HUDEVT_ABORTED] = ORB_STATE_UP,
    [HUDEVT_CMP_PERSIST_REPLY] = ORB_STATE_UP | ORB_STATE_DOWN,
    [HUDEVT_EGRESS_STOP] = ORB_STATE_SLOW,
    [HUDEVT_EXPIRED] = ORB_STATE_UP,
    [HUDEVT_FLOW_INIT] = ORB_STATE_SLOW,
    [HUDEVT_OOB] = ORB_STATE_UP,
    [HUDEVT_PAUSE_EGRESS] = ORB_STATE_SLOW,
    [HUDEVT_SENT] = ORB_STATE_SLOW,
    [HUDEVT_SYN] = ORB_STATE_UP,
    [HUDEVT_SYNACK] = ORB_STATE_UP,

    /* Direct events */
    [HUDEVT_CALLBACK] = ORB_STATE_SLOW,
    [HUDEVT_COMPRESS] = ORB_STATE_UP | ORB_STATE_DOWN,
    [HUDEVT_CRYPTO] = ORB_STATE_UP | ORB_STATE_DOWN,
    [HUDEVT_DECOMPRESS] = ORB_STATE_UP | ORB_STATE_DOWN,
    [HUDEVT_RESOLVED] = ORB_STATE_UP | ORB_STATE_DOWN,
    [HUDEVT_TCL] = ORB_STATE_UP | ORB_STATE_DOWN,
    [HUDEVT_TCL_CHILD] = ORB_STATE_UP | ORB_STATE_DOWN,
    [HUDEVT_TIMER] = ORB_STATE_UP | ORB_STATE_DOWN,

    /* Asynchronous events */
    [HUDEVT_ACCEPTED] = ORB_STATE_SLOW,
    [HUDEVT_CLOSED] = ORB_STATE_UP,
    [HUDEVT_CONNECTED] = ORB_STATE_UP,
    [HUDEVT_EOF] = ORB_STATE_UP,
    [HUDEVT_INGRESS_ABORT] = ORB_STATE_UP,
    [HUDEVT_MESSAGE] = ORB_STATE_UP,
    [HUDEVT_MESSAGE_DONE] = ORB_STATE_UP,
    [HUDEVT_META] = ORB_STATE_UP,
    [HUDEVT_REQUEST] = ORB_STATE_UP,
    [HUDEVT_REQUEST_DONE] = ORB_STATE_UP,
    [HUDEVT_RESPONSE] = ORB_STATE_UP,
    [HUDEVT_RESPONSE_DONE] = ORB_STATE_UP,
    [HUDEVT_RESPONSE_WITH_REQUEST] = ORB_STATE_UP,
    [HUDEVT_RESPONSE_WITH_REQUEST_DONE] = ORB_STATE_UP,
    [HUDEVT_SHUTDOWN] = ORB_STATE_UP,
    [HUDEVT_USER_EOM] = ORB_STATE_UP,
    [HUDEVT_USER_REQUEST] = ORB_STATE_UP,
    [HUDEVT_USER_RESPONSE] = ORB_STATE_UP,
};

static void
hud_orbit_handler_fastpath(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    struct hud_orbit *orb;
    UINT8 state = hud_orbit_msg_state[msg];
    UINT64 orig_state;

    if (unlikely(state & ORB_STATE_SLOW)) {
        hud_orbit_handler(node, msg, uf, data);
    } else {
        orb = HUDNODE_ORBIT(node);
        ORB_TRACEF(orb, uf, "%s", hud_msg_name_str(msg));

        orig_state = hud_orbit_state;
        hud_orbit_state = INT(node) + state;
        orb->handler(node, msg, uf, data);
        hud_orbit_state = orig_state;
    }
}

static err_t
hud_orbit_process_ingress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    UINT64 orig_state;

    ORB_TRACEF(orb, uf, "%u", xb->len);

    /* If we are aborting, silently absorb all data */
    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS)) {
        xbuf_free(xb);
        goto out;
    }

    if (ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_UP)) {
        if (ORB_FLAG_TEST(orb, ORB_FG_EXISTS_INGRESS_OUT | ORB_FG_ACCEPTED)) {
            /* Queue ingress behind existing ingress. */
            orig_state = hud_orbit_state;
            hud_orbit_state = INT(node) + ORB_STATE_UP;
            hud_orbit_process_upper(node, uf, xb);
            hud_orbit_state = orig_state;
        } else {
            /* No ingress queued - straight passthrough. */
            uflow_process_upper(node, uf, xb);
        }
        goto out;
    }

    if (ORB_FLAG_TEST(orb, ORB_FG_HAIRPIN) &&
            (orb->egress_len > orb->high_watermark)) {
        goto queue;
    }

    /* Attempt to deliver if the queue is empty, and we are not paused. */
    if (!ORB_FLAG_TEST(orb, ORB_FG_PAUSE_INGRESS | ORB_FG_EXISTS_INGRESS)) {
        orig_state = hud_orbit_state;
        hud_orbit_state = INT(node) + ORB_STATE_UP;
        orb->ingress_handler(node, uf, xb);
        hud_orbit_state = orig_state;
        if (likely(xb->len == 0)) {
            goto out;
        }
        ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS);
    }

queue:
    orb->ingress_len += xb->len;
    ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u", xb->len,
            orb->ingress_len);
    hud_orbit_enqueue_xb(orb, uf, xb, ORB_F_INGRESS);
    orb->node.s_ingress = hud_orbit_process_ingress;
    hudnode_set_handler(&orb->node, hud_orbit_handler);

    /* Attempt to turn off ingress if we have too much */
    hud_orbit_apply_ingress_flow_control(orb, uf);

out:
    return ERR_OK;
}

static err_t
hud_orbit_process_egress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    UINT64 orig_state;

    ORB_TRACEF(orb, uf, "%u", xb->len);

    /* If we are aborting, silently absorb all data */
    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS)) {
        xbuf_free(xb);
        goto out;
    }

    if (ORB_FLAG_TEST(orb, ORB_FG_PASSTHRU_DOWN)) {
        if (ORB_FLAG_TEST(orb, ORB_FG_EXISTS_EGRESS_OUT)) {
            /* Queue egress behind existing egress. */
            orig_state = hud_orbit_state;
            hud_orbit_state = INT(node) + ORB_STATE_DOWN;
            hud_orbit_process_lower(node, uf, xb);
            hud_orbit_state = orig_state;
        } else {
            /* No egress queued - straight passthrough. */
            uflow_process_lower(node, uf, xb);
        }
        goto out;
    }

    /* Don't accept the payload if we are paused or blocked */
    if (ORB_FLAG_TEST(orb, ORB_FG_PAUSE_EGRESS | ORB_FG_BLOCKED_DOWN)) {
        ORB_FLAG_SET(orb, ORB_FG_SENT);
        ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
        goto out;
    }

    /* Don't accept the payload if we have too much and not plugged */
    if (!ORB_FLAG_TEST(orb, ORB_FG_PAUSE_EGRESS_OUT) &&
            (orb->egress_len > orb->high_watermark)) {
        ORB_FLAG_SET(orb, ORB_FG_SENT);
        ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
        goto out;
    }

    /* Attempt to deliver if the egress queue is empty */
    if (!ORB_FLAG_TEST(orb, ORB_FG_EXISTS_EGRESS)) {
        orig_state = hud_orbit_state;
        hud_orbit_state = INT(node) + ORB_STATE_DOWN;
        orb->egress_handler(node, uf, xb);
        hud_orbit_state = orig_state;
        if (likely(xb->len == 0)) {
            goto out;
        }
        ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS);
    }

    hud_orbit_report_mu_delta(orb, uf, orb->egress_len + xb->len);
    ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u", xb->len,
            orb->egress_len);
    hud_orbit_enqueue_xb(orb, uf, xb, ORB_F_EGRESS);
    orb->node.s_egress = hud_orbit_process_egress;
    hudnode_set_handler(&orb->node, hud_orbit_handler);

out:
    return ERR_OK;
}

static err_t
hud_orbit_process_ingress_fastpath(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    UINT64 orig_state;

    ORB_TRACEF(orb, uf, "%u", xb->len);

#if HUD_DEBUG
    /* Make sure we should be on the fastpath */
    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS | ORB_FG_PASSTHRU_UP |
            ORB_FG_PAUSE_INGRESS | ORB_FG_EXISTS_INGRESS | ORB_FG_PACKET)) {
        OOPS("Orbits ingress shouldn't be fast-pathed");
        return hud_orbit_process_ingress(node, uf, xb);
    }
#endif

    if (ORB_FLAG_TEST(orb, ORB_FG_HAIRPIN) &&
            (orb->egress_len > orb->high_watermark)) {
        goto queue;
    }

    orig_state = hud_orbit_state;
    hud_orbit_state = INT(node) + ORB_STATE_UP;
    orb->ingress_handler(node, uf, xb);
    hud_orbit_state = orig_state;
    if (likely(xb->len == 0)) {
        goto out;
    }
    ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS);

queue:
    node->s_ingress = hud_orbit_process_ingress;
    hudnode_set_handler(&orb->node, hud_orbit_handler);

    orb->ingress_len += xb->len;
    hud_orbit_enqueue_xb(orb, uf, xb, ORB_F_INGRESS);

    /* Attempt to turn off ingress if we have too much */
    hud_orbit_apply_ingress_flow_control(orb, uf);

out:
    return ERR_OK;
}

static err_t
hud_orbit_process_egress_fastpath(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    UINT64 orig_state;

    ORB_TRACEF(orb, uf, "%u", xb->len);

#if HUD_DEBUG
    /* Make sure we should be on the fastpath */
    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_PASSTHRU_DOWN |
                ORB_FG_PAUSE_EGRESS | ORB_FG_BLOCKED_DOWN |
                ORB_FG_EXISTS_EGRESS | ORB_FG_PACKET) ||
            (orb->egress_len > orb->high_watermark)) {
        OOPS("Orbits egress shouldn't be fast-pathed");
        return hud_orbit_process_egress(node, uf, xb);
    }
#endif

    orig_state = hud_orbit_state;
    hud_orbit_state = INT(node) + ORB_STATE_DOWN;
    orb->egress_handler(node, uf, xb);
    hud_orbit_state = orig_state;
    if (likely(xb->len == 0)) {
        goto out;
    }
    ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS);
    node->s_egress = hud_orbit_process_egress;
    hudnode_set_handler(&orb->node, hud_orbit_handler);

    hud_orbit_report_mu_delta(orb, uf, orb->egress_len + xb->len);
    hud_orbit_enqueue_xb(orb, uf, xb, ORB_F_EGRESS);

out:
    return ERR_OK;
}

static err_t
hud_orbit_process_ingress_pkt(struct hudnode *node, union uflow *uf,
        struct packet *pkt)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    err_t err = ERR_OK;
    UINT64 orig_state;

    ORB_TRACEF(orb, uf, "%u", pkt->len);

    /* If we are aborting, silently absorb all data */
    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS)) {
        packet_free(pkt);
        goto out;
    }

    /* Always deliver packets */
    orig_state = hud_orbit_state;
    hud_orbit_state = INT(node) + ORB_STATE_UP;
    err = orb->ingress_handler(node, uf, (struct xbuf *)pkt);
    hud_orbit_state = orig_state;

out:
    return err;
}

static err_t
hud_orbit_process_egress_pkt(struct hudnode *node, union uflow *uf,
        struct packet *pkt)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    err_t err = ERR_OK;
    UINT64 orig_state;

    ORB_TRACEF(orb, uf, "%u", pkt->len);

    /* If we are aborting, silently absorb all data */
    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS)) {
        packet_free(pkt);
        goto out;
    }

    /* Always deliver packets */
    orig_state = hud_orbit_state;
    hud_orbit_state = INT(node) + ORB_STATE_DOWN;
    err = orb->egress_handler(node, uf, (struct xbuf *)pkt);
    hud_orbit_state = orig_state;

out:
    return err;
}

void
hud_orbit_proxy_process_egress_peer(union uflow *uf, struct xbuf *xb)
{
    union uflow *peer = uflow_peer(uf);
    struct hudnode *node = uflow_top_node(peer);
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    ORB_TRACEF(orb, uf, "%u", xb->len);

    /* SHUTDOWN or ABORT has egressed */
    if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_FREE))) {
        ORB_TRACEF(orb, peer, "Sunk %u", xb->len);
        xbuf_free(xb);
        goto out;
    }

    /* Ignore empty egress */
    if (unlikely(xb->len == 0)) {
        goto out;
    }

    if (!ORB_FLAG_TEST(orb, ORB_FG_PAUSE_EGRESS_OUT |
            ORB_FG_BLOCKED_DOWN | ORB_FG_EXISTS_EGRESS_OUT)) {
        /* Attempt to deliver if the queue is empty, and we are not paused. */
        uflow_process_lower(node, peer, xb);
        if (likely(xb->len == 0)) {
            goto out;
        }
        ORB_FLAG_SET(orb, ORB_FG_BLOCKED_DOWN);
    }

    /*
     * Queue the payload if we are paused or blocked,
     * but send a HUDCTL_XOFF down chain when high_watermark is exceeded.
     *
     * Account the buffered egress as memory units against the proxy.  This is
     * a top-node orbit (the proxy itself) holding egress data on behalf of a
     * blocked peer; ORB_FG_BLOCKED_DOWN is set above when we begin buffering,
     * so hud_orbit_report_mu_delta() reports the MU increase to the proxy in
     * the same manner as the orbitized hudnodes stacked above it.
     */
    hud_orbit_report_mu_delta(orb, peer, orb->egress_len + xb->len);
    ORB_TRACEF(orb, peer, "enqueued %u bytes totaling %u", xb->len,
            orb->egress_len);

    if (!ORB_FLAG_TEST(orb, ORB_FG_PEER_XOFF) &&
            (orb->egress_len > orb->high_watermark)) {
        ORB_FLAG_SET(orb, ORB_FG_PEER_XOFF);
        if (ha_active_unit(uflow_get_connflow(uf)->ha_unit)) {
            uflow_proxy_handle(HUDCTL_XOFF, uf, (void *)TRUE);
        }
    }

    hud_orbit_enqueue_xb(orb, peer, xb, ORB_F_EGRESS_OUT);
    orb->node.s_egress = hud_orbit_process_egress;

out:
    return;
}

void
hud_orbit_set_watermarks(struct hudnode *node, UINT32 high, UINT32 low)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    /*
     * Numbers will change, say during autotuning, but won't take effect
     * immediately. Either after we have buffered enough or
     * drained enough.
     */
    orb->high_watermark = high;
    orb->low_watermark = low;
}

void
hud_orbit_get_watermarks(struct hudnode *node, UINT32 *high, UINT32 *low)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    *high = orb->high_watermark;
    *low = orb->low_watermark;
}

void
hud_orbit_init(struct hudnode *node, hud_handler handler)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    hud_orbit_queue_init(&orb->queue);
    orb->message_size = ORB_DEFAULT_MESSAGE_SIZE;
    orb->handler = (stream_handler) handler;
    orb->ingress_handler = node->s_ingress;
    orb->egress_handler = node->s_egress;
    hudnode_set_handler(node, hud_orbit_handler);
    node->s_ingress = hud_orbit_process_ingress_fastpath;
    orb->high_watermark = ORB_WATERMARK;
    orb->low_watermark = ORB_WATERMARK / 2;
    if (!HUDNODE_IS_TOP(&orb->node)) {
        node->s_egress = hud_orbit_process_egress_fastpath;
    }
}

void
hud_orbit_stream_init(struct hudnode *node, struct hudnode *pnode)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct hud_orbit *porb = HUDNODE_ORBIT(pnode);

    memset(orb, 0, HUD_ORBIT_SIZE);

    hud_orbit_queue_init(&orb->queue);
    orb->message_size = ORB_DEFAULT_MESSAGE_SIZE;
    orb->handler = porb->handler;
    orb->ingress_handler = porb->ingress_handler;
    orb->egress_handler = porb->egress_handler;
    orb->high_watermark = ORB_WATERMARK;
    orb->low_watermark = ORB_WATERMARK / 2;
}

static err_t
hud_orbit_process_aborted(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    /* Sink all data */
    xbuf_free(xb);
    return ERR_OK;
}

static void
hud_orbit_handler_aborted(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    UINT64 orig_state;

    ORB_TRACEF(orb, uf, "%s", hud_msg_name_str(msg));

    if (msg == HUDEVT_FLOW_INIT) {
        /* Reset flags as previous state is gone */
        orb->flags = 0;
        DBG_ASSERT("node has queued",orb->ingress_len == 0);
        DBG_ASSERT("node has queued",orb->egress_len == 0);
        node->s_ingress = hud_orbit_process_ingress_fastpath;
        if (!HUDNODE_IS_TOP(node)) {
            node->s_egress = hud_orbit_process_egress_fastpath;
        } else {
            node->s_egress = hud_orbit_process_egress;
        }
        hudnode_set_handler(&orb->node, hud_orbit_handler_fastpath);
        orig_state = hud_orbit_state;
        hud_orbit_state = INT(node) + ORB_STATE_UP;
        orb->handler(node, msg, uf, data);
        hud_orbit_state = orig_state;
    } else if (msg == HUDCTL_PERFORM_METHOD) {
        /* Forward methods */
        orb->handler(node, msg, uf, data);
    } else {
        /* Absorb everything else */
        hud_orbit_free_msg_data(msg, data);
    }
}

void
hud_orbit_handle_teardown(struct hudnode *node, union uflow *uf)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct hud_orb_entry *head_entry = NULL;
    struct hud_orb_entry *entry;

    if (ORB_FLAG_TEST(orb, ORB_FG_FLUSHING)) {
        /* Retain a flushing entry owned by hud_orbit_flush() */
        head_entry = hud_orbit_pop_queue(&orb->queue);
    }

    /* Kill all the outstanding entries */
    while (!hud_orbit_queue_empty(&orb->queue)) {
        entry = hud_orbit_pop_queue(&orb->queue);
        if (unlikely(head_entry != NULL)) {
            enum orb_flags flags = hud_orbit_entry_flags_get(entry);
            UINT32 len;

            if (!hud_orbit_entry_is_xb(entry)) {
                len = orb->message_size;
            } else {
                len = hud_orbit_entry_xb(entry)->len;
            }
            switch (flags) {
            case ORB_F_EGRESS:
            case ORB_F_EGRESS_OUT:
                hud_orbit_report_mu_delta(orb, uf, orb->egress_len - len);
                break;
            case ORB_F_INGRESS:
            case ORB_F_INGRESS_OUT:
                orb->ingress_len -= len;
                break;
            default:
                break;
            }
        }
        hud_orbit_free_entry_contents(entry);
        hud_orbit_free_entry(entry);
    }
    ORB_FLAG_UNSET(orb, ORB_FG_EXISTS_INGRESS);
    ORB_FLAG_UNSET(orb, ORB_FG_EXISTS_INGRESS_OUT);
    ORB_FLAG_UNSET(orb, ORB_FG_EXISTS_EGRESS);
    ORB_FLAG_UNSET(orb, ORB_FG_EXISTS_EGRESS_OUT);
    ORB_FLAG_SET(orb, ORB_FG_FREE);
    ORB_FLAG_SET(orb, ORB_FG_DROP_EGRESS);
    orb->node.s_ingress = hud_orbit_process_aborted;
    orb->node.s_egress = hud_orbit_process_aborted;
    hudnode_set_handler(&orb->node, hud_orbit_handler_aborted);
    if (head_entry != NULL) {
        hud_orbit_queue_insert_head_entry(&orb->queue, head_entry);
    } else {
        /* Payload no longer buffered */
        hud_orbit_report_mu_delta(orb, uf, 0);
        orb->ingress_len = 0;
    }
}

void
hud_orbit_handle_teardown_lower(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    hud_orbit_handle_teardown(node, uf);
    if (ORB_FLAG_TEST(orb, ORB_FG_FLUSHING) ||
           hud_orbit_state_mismatch(node, ORB_STATE_DOWN)) {
        uflowQ_handle_lower(node, msg, uf, data);
    } else {
        uflow_handle_lower(node, msg, uf, data);
    }
}

void
hud_orbit_handle_async_below(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    /* A message causes an implicit unplug */
    hud_orbit_unplug_egress(node, uf);

    if ((msg == HUDCTL_SHUTDOWN) || (msg == HUDCTL_EGRESS_ABORT)) {
        ORB_FLAG_SET(orb, ORB_FG_DROP_EGRESS);
        if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
            orb->node.s_egress = hud_orbit_process_egress;
        }
        hudnode_set_handler(&orb->node, hud_orbit_handler);
    } else if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_FREE))) {
        /* Aborting or shutdown, just ignore this message */
        hud_orbit_free_msg_data(msg, data);
        goto out;
    }

    if (ORB_FLAG_TEST(orb,
            ORB_FG_EXISTS_EGRESS_OUT | ORB_FG_CALLBACK)) {
        hud_orbit_enqueue_msg(orb, msg, uf, data, ORB_F_EGRESS_OUT);
        hud_orbit_report_mu_delta(orb, uf, orb->egress_len + orb->message_size);
        if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
            orb->node.s_egress = hud_orbit_process_egress;
        }
        goto out;
    }

    if (!hud_orbit_state_mismatch(node, ORB_STATE_DOWN)) {
        uflow_handle_lower(node, msg, uf, data);
    } else {
        uflowQ_handle_lower(node, msg, uf, data);
    }
out:
    return;
}

void
hud_orbit_handle_abort_above(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_DROP_INGRESS);
    if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
        orb->node.s_ingress = hud_orbit_process_ingress;
    }
    hudnode_set_handler(&orb->node, hud_orbit_handler);
    uflow_handle_upper(node, msg, uf, data);
}

void hud_orbit_handle_async_above(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    BOOL accepted = FALSE;

    /* A message causes an implicit unplug */
    if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_PAUSE_INGRESS_OUT))) {
        ORB_FLAG_UNSET(orb, ORB_FG_PAUSE_INGRESS_OUT);

        /* Do a complete flush when safe */
        hud_orbit_trigger_flush(orb, uf);
    }

    if ((msg == HUDEVT_SHUTDOWN) || (msg == HUDEVT_EOF) ||
            (msg == HUDEVT_INGRESS_ABORT)) {
        ORB_FLAG_SET(orb, ORB_FG_DROP_INGRESS);
        if (!ORB_FLAG_TEST(orb, ORB_FG_PACKET)) {
            orb->node.s_ingress = hud_orbit_process_ingress;
        }
        hudnode_set_handler(&orb->node, hud_orbit_handler);
    } else if (ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS | ORB_FG_FREE) &&
            (msg != HUDEVT_CLOSED)) {
        /* Aborting or shutdown, just ignore this message */
        hud_orbit_free_msg_data(msg, data);
        goto out;
    }

    if (ORB_FLAG_TEST(orb,
            ORB_FG_EXISTS_INGRESS_OUT | ORB_FG_CALLBACK)) {
        hud_orbit_enqueue_msg(orb, msg, uf, data, ORB_F_INGRESS_OUT);
        orb->ingress_len += orb->message_size;
        goto out;
    }

    if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_ACCEPTED))) {
        ORB_FLAG_UNSET(orb, ORB_FG_ACCEPTED);
        ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
        accepted = TRUE;
    }

    if (!hud_orbit_state_mismatch(node, ORB_STATE_UP)) {
        /* Was HUDEVT_ACCEPTED held? */
        if (accepted && (msg != HUDEVT_EOF) && (msg != HUDEVT_SHUTDOWN) &&
                (msg != HUDEVT_INGRESS_ABORT)) {
            uflow_handle_upper(node, HUDEVT_ACCEPTED, uf, NULL);
        }
        uflow_handle_upper(node, msg, uf, data);
    } else {
        /* Was HUDEVT_ACCEPTED held? */
        if (accepted && (msg != HUDEVT_EOF) && (msg != HUDEVT_SHUTDOWN) &&
                (msg != HUDEVT_INGRESS_ABORT)) {
            uflowQ_handle_upper(node, HUDEVT_ACCEPTED, uf, NULL);
        }
        uflowQ_handle_upper(node, msg, uf, data);
    }
out:
    return;
}

void
hud_orbit_proxy_handle(union uflow *src_uf, union uflow *dest_uf,
        hud_msg_t msg, void *data)
{
    struct hudnode *src_node = uflow_top_node(src_uf);
    struct hudnode *dest_node = uflow_top_node(dest_uf);
    struct hud_orbit *orb = HUDNODE_ORBIT(dest_node);

    if (unlikely(IS_HUDEVT_MSG(msg))) {
        OOPS("Unsupported message type");
        goto out;
    }

    ORB_TRACEF(orb, dest_uf, "%s", hud_msg_name_str(msg));

    if ((msg != HUDCTL_TEARDOWN) && (msg != HUDCTL_ABORT)) {
        if (IS_HUDCTL_SYNC_MSG(msg)) {
            /* Deliver the synchronous message */
            orb->handler(dest_node, msg, dest_uf, data);
            goto out;
        }

        /* Aborting or shutdown, just ignore this message */
        if (ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_FREE)) {
            hud_orbit_free_msg_data(msg, data);
            goto out;
        }
    }

    if (!hud_orbit_state_mismatch(src_node, ORB_STATE_UP)) {
        uflow_handle(dest_node, msg, dest_uf, data);
    } else {
        uflowQ_handle(dest_node, msg, dest_uf, data);
    }

out:
    return;
}

void
hud_orbit_process_lower(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    ORB_TRACEF(orb, uf, "process_lower %u", xb->len);

    /* Ignore empty egress */
    if (unlikely(xb->len == 0)) {
        goto out;
    }

    if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_FREE))) {
        ORB_TRACEF(orb, uf, "Sunk %u", xb->len);
        xbuf_free(xb);
        goto out;
    }

    if (!ORB_FLAG_TEST(orb, ORB_FG_EXISTS_EGRESS_OUT | ORB_FG_BLOCKED_DOWN |
            ORB_FG_PAUSE_EGRESS_OUT)) {
        if (!hud_orbit_state_mismatch(node, ORB_STATE_DOWN)) {
            /* Deliver the data */
            uflow_process_lower(node, uf, xb);
            if (likely(xb->len == 0)) {
                goto out;
            }
            ORB_FLAG_SET(orb, ORB_FG_BLOCKED_DOWN);
        } else {
            /* The only reason we can't send the data is the direction */
            hud_orbit_trigger_flush(orb, uf);
        }
    }

    hud_orbit_report_mu_delta(orb, uf, orb->egress_len + xb->len);
    ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u", xb->len,
            orb->egress_len);
    hud_orbit_enqueue_xb(orb, uf, xb, ORB_F_EGRESS_OUT);
    orb->node.s_egress = hud_orbit_process_egress;
out:
    return;
}

void
hud_orbit_process_upper(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    ORB_TRACEF(orb, uf, "process_upper %u", xb->len);

    /* Ignore empty ingress */
    if (unlikely(xb->len == 0)) {
        goto out;
    }

    if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS | ORB_FG_FREE))) {
        ORB_TRACEF(orb, uf, "Sunk %u", xb->len);
        xbuf_free(xb);
        goto out;
    }

    if (!ORB_FLAG_TEST(orb,
            ORB_FG_EXISTS_INGRESS_OUT | ORB_FG_PAUSE_INGRESS_OUT)) {
        if (!hud_orbit_state_mismatch(node, ORB_STATE_UP)) {
            /* Was HUDEVT_ACCEPTED held? */
            if (ORB_FLAG_TEST(orb, ORB_FG_ACCEPTED)) {
                ORB_FLAG_UNSET(orb, ORB_FG_ACCEPTED);
                ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
                uflow_handle_upper(node, HUDEVT_ACCEPTED, uf, NULL);
            }

            /* Deliver the data */
            uflow_process_upper(node, uf, xb);
            goto out;
        }

        /* The only reason we can't send the data is the direction */
        hud_orbit_trigger_flush(orb, uf);
    }

    orb->ingress_len += xb->len;
    ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u", xb->len,
            orb->ingress_len);
    hud_orbit_enqueue_xb(orb, uf, xb, ORB_F_INGRESS_OUT);
out:
    return;
}

void
hud_orbit_process_stream(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct hudnode *parent_node = HUDNODE_NODE(node->parent);

    ORB_TRACEF(orb, uf, "process_stream %u", xb->len);

    /* Ignore empty ingress */
    if (unlikely(xb->len == 0)) {
        goto out;
    }

    if (unlikely(ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS | ORB_FG_FREE))) {
        ORB_TRACEF(orb, uf, "Sunk %u", xb->len);
        xbuf_free(xb);
        goto out;
    }

    if (!ORB_FLAG_TEST(orb,
            ORB_FG_EXISTS_INGRESS_OUT | ORB_FG_PAUSE_INGRESS_OUT)) {
        if (!hud_orbit_state_mismatch(parent_node, ORB_STATE_UP)) {
            /* Was HUDEVT_ACCEPTED held? */
            if (ORB_FLAG_TEST(orb, ORB_FG_ACCEPTED)) {
                ORB_FLAG_UNSET(orb, ORB_FG_ACCEPTED);
                ORB_FLAG_UNSET(orb, ORB_FG_INSERT);
                uflow_handle_upper(node, HUDEVT_ACCEPTED, uf, NULL);
            }

            /* Deliver the data */
            uflow_process_upper(node, uf, xb);
            goto out;
        }

        /* The only reason we can't send the data is the direction */
        hud_orbit_trigger_flush(orb, uf);
    }

    orb->ingress_len += xb->len;
    ORB_TRACEF(orb, uf, "enqueued %u bytes totaling %u", xb->len,
            orb->ingress_len);
    hud_orbit_enqueue_xb(orb, uf, xb, ORB_F_INGRESS_OUT);
out:
    return;
}

void
hud_orbit_payload_lower(struct hudnode *node, union uflow *uf,
        BYTE *payload, SIZE payload_len)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct xbuf xb_payload;
    struct xbuf *xb = hud_orbit_queue_tail_xb_match(&orb->queue,
            ORB_F_EGRESS_OUT);
    if (xb != NULL) {
        if (xbuf_append(xb, payload, payload_len) != ERR_OK) {
            hud_orbit_aborted(orb, uf,  "Internal delivery error");
        }
        hud_orbit_report_mu_delta(orb, uf, orb->egress_len + payload_len);
    } else {
        xbuf_embed_init(&xb_payload, uflow_mss(uf));
        if (xbuf_append(&xb_payload, payload, payload_len) != ERR_OK) {
            hud_orbit_aborted(orb, uf,  "Internal delivery error");
        } else {
            hud_orbit_process_lower(node, uf, &xb_payload);
        }
        xbuf_free(&xb_payload);
    }
}

void
hud_orbit_payload_upper(struct hudnode *node, union uflow *uf,
        BYTE *payload, SIZE payload_len)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct xbuf xb_payload;
    struct xbuf *xb;

    if (unlikely(payload_len == 0)) {
        goto out;
    }

    xb = hud_orbit_queue_tail_xb_match(&orb->queue, ORB_F_INGRESS_OUT);
    if (xb != NULL) {
        if (xbuf_append(xb, payload, payload_len) != ERR_OK) {
            hud_orbit_aborted(orb, uf,  "Internal delivery error");
        }
        orb->ingress_len += payload_len;
    } else {
        xbuf_embed_init(&xb_payload, uflow_mss(uf));
        if (xbuf_append(&xb_payload, payload, payload_len) != ERR_OK) {
            hud_orbit_aborted(orb, uf,  "Internal delivery error");
        } else {
            hud_orbit_process_upper(node, uf, &xb_payload);
        }
        xbuf_free(&xb_payload);
    }

out:
    return;
}

void
hud_orbit_pause_ingress(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS);
    orb->node.s_ingress = hud_orbit_process_ingress;
    hudnode_set_handler(&orb->node, hud_orbit_handler);
}

void
hud_orbit_pause_egress(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS);
    orb->node.s_egress = hud_orbit_process_egress;
    hudnode_set_handler(&orb->node, hud_orbit_handler);
}

void
hud_orbit_pause(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS);
    ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS);
    orb->node.s_ingress = hud_orbit_process_ingress;
    orb->node.s_egress = hud_orbit_process_egress;
    hudnode_set_handler(&orb->node, hud_orbit_handler);
}

void
hud_orbit_proxy_pause(union uflow *uf)
{
    hud_orbit_pause(uflow_top_node(uf));
    uf = uflow_peer(uf);
    if (uf != NULL) {
        hud_orbit_pause(uflow_top_node(uf));
    }
}

void
hud_orbit_unpause_ingress(struct hudnode *node, union uflow *uf)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (ORB_FLAG_TEST(orb, ORB_FG_PAUSE_INGRESS)) {
        ORB_FLAG_UNSET(orb, ORB_FG_PAUSE_INGRESS);
        hud_orbit_check_ingress_fastpath(orb);
        hud_orbit_check_handler_fastpath(orb);

        /* Flush when safe */
        hud_orbit_trigger_flush(orb, uf);
    }
}

void
hud_orbit_unpause_egress(struct hudnode *node, union uflow *uf)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (ORB_FLAG_TEST(orb, ORB_FG_PAUSE_EGRESS)) {
        ORB_FLAG_UNSET(orb, ORB_FG_PAUSE_EGRESS);
        hud_orbit_check_egress_fastpath(orb);
        hud_orbit_check_handler_fastpath(orb);

        /* Flush when safe */
        hud_orbit_trigger_flush(orb, uf);
    }
}

void
hud_orbit_unpause(struct hudnode *node, union uflow *uf)
{
    hud_orbit_unpause_ingress(node, uf);
    hud_orbit_unpause_egress(node, uf);
}

void
hud_orbit_proxy_unpause(union uflow *uf)
{
    hud_orbit_unpause(uflow_top_node(uf), uf);
    uf = uflow_peer(uf);
    if (uf != NULL) {
        hud_orbit_unpause(uflow_top_node(uf), uf);
    }
}

void
hud_orbit_plug_ingress(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS_OUT);
}

void
hud_orbit_plug_egress(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    if (unlikely(!ORB_FLAG_TEST(orb, ORB_FG_BLOCKED_DOWN))) {
        ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS_OUT);
    }
}

void
hud_orbit_unplug_ingress(struct hudnode *node, union uflow *uf)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (ORB_FLAG_TEST(orb, ORB_FG_PAUSE_INGRESS_OUT)) {
        ORB_FLAG_UNSET(orb, ORB_FG_PAUSE_INGRESS_OUT);

        /* Do a complete flush when safe */
        hud_orbit_trigger_flush(orb, uf);
    }
}

void
hud_orbit_unplug_egress(struct hudnode *node, union uflow *uf)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (ORB_FLAG_TEST(orb, ORB_FG_PAUSE_EGRESS_OUT)) {
        ORB_FLAG_UNSET(orb, ORB_FG_PAUSE_EGRESS_OUT);

        if (!ORB_FLAG_TEST(orb, ORB_FG_SENT | ORB_FG_PEER_XOFF |
                ORB_FG_COMPLETE | ORB_FG_CALLBACK | ORB_FG_FLUSHING |
                ORB_FG_EXISTS_INGRESS | ORB_FG_EXISTS_EGRESS) &&
                ORB_FLAG_TEST(orb, ORB_FG_EXISTS_EGRESS_OUT)) {
            hud_orbit_flush(orb, uf);
        } else {
            /* Do a complete flush when safe */
            hud_orbit_trigger_flush(orb, uf);
        }
    }
}

void
hud_orbit_complete(struct hudnode *node, union uflow *uf)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (!ORB_FLAG_TEST(orb, ORB_FG_COMPLETE)) {
        ORB_FLAG_SET(orb, ORB_FG_COMPLETE);
        hud_orbit_set_passthru_ingress(node, uf, TRUE);
        hud_orbit_set_passthru_egress(node, uf, TRUE);

        /* Flush when safe to trigger completion */
        hud_orbit_trigger_flush(orb, uf);
    }
}

void
hud_orbit_pushback(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct hud_orb_entry *entry;

    switch (msg) {
    case HUDEVT_COMPRESS:
    case HUDEVT_DECOMPRESS:
    case HUDEVT_CALLBACK:
    case HUDEVT_CRYPTO:
    case HUDEVT_RESOLVED:
    case HUDEVT_TCL:
    case HUDEVT_TCL_CHILD:
    case HUDEVT_TIMER:
    case HUDCTL_TEARDOWN:
    case HUDCTL_ABORT:
    case HUDCTL_ENABLE:
    case HUDCTL_PERFORM_METHOD:
    case HUDCTL_URGENT:
    case HUDCTL_CONNECT:
    case HUDCTL_GET_REMOTE:
    case HUDCTL_HA_MIRROR_CONTEXT:
    case HUDCTL_ICMP:
    case HUDCTL_OOB:
    case HUDCTL_PERSIST_METHOD:
    case HUDCTL_QUERY_MSS:
    case HUDCTL_SET_SERVER:
    case HUDCTL_SSL_FWDP_SRV_HS_DONE:
    case HUDCTL_SYNACK:
        OOPS("Cannot delay a synchronous event");

        /* This message should not be delayed */
        hud_orbit_aborted(orb, uf,  "Internal delivery error");
        goto out;
    default:
        break;
    }

    /* Aborting or shutdown, just ignore this message */
    if ((ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_FREE) &&
                IS_HUDCTL_MSG(msg)) ||
            (ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS | ORB_FG_FREE) &&
                IS_HUDEVT_MSG(msg))) {
        hud_orbit_free_msg_data(msg, data);
        goto out;
    }

    if (IS_HUDEVT_MSG(msg)) {
        entry = hud_orbit_create_entry_msg(msg, data, 0, ORB_F_INGRESS);
        if (entry == NULL) {
            hud_orbit_aborted(orb, uf,  "Internal delivery error");
            goto out;
        }
        ORB_FLAG_SET(orb, ORB_FG_EXISTS_INGRESS);
        ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS);
        orb->node.s_ingress = hud_orbit_process_ingress;
    } else {
        entry = hud_orbit_create_entry_msg(msg, data, 0, ORB_F_EGRESS);
        if (entry == NULL) {
            hud_orbit_aborted(orb, uf,  "Internal delivery error");
            goto out;
        }
        ORB_FLAG_SET(orb, ORB_FG_EXISTS_EGRESS);
        ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS);
        orb->node.s_egress = hud_orbit_process_egress;
    }
    hudnode_set_handler(&orb->node, hud_orbit_handler);

    hud_orbit_queue_insert_head_entry(&orb->queue, entry);

    /* Pause */
    if (IS_HUDEVT_MSG(msg)) {
        orb->ingress_len += orb->message_size;

        /* Attempt to turn off ingress if we have too much */
        hud_orbit_apply_ingress_flow_control(orb, uf);
    } else {
        hud_orbit_report_mu_delta(orb, uf, orb->egress_len + orb->message_size);
        hud_orbit_apply_egress_flow_control(orb, uf);
    }

out:
    return;
}

static void
hud_orbit_pushback_data(struct hudnode *node, union uflow *uf,
        struct xbuf *xb, enum orb_flags flags)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    struct hud_orb_entry *entry;
    struct xbuf *xb_head = hud_orbit_queue_head_xb_match(&orb->queue, flags);

    if (xb_head != NULL) {
        /* Prepend xb onto xb_head */
        xbuf_merge_compact(xb, xb_head);
        xbuf_merge(xb_head, xb);
    } else {
        entry = hud_orbit_create_entry_xb(xb, flags);
        if (entry == NULL) {
            hud_orbit_aborted(orb, uf,  "Internal delivery error");
        } else {
            hud_orbit_queue_insert_head_entry(&orb->queue, entry);
            ORB_FLAG_SET(orb, ORB_FG_EXISTS_INGRESS << flags);
            hudnode_set_handler(&orb->node, hud_orbit_handler);
        }
    }
}

void
hud_orbit_pushback_ingress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_INGRESS | ORB_FG_FREE)) {
        /* Aborting or shutdown, just ignore this data */
        xbuf_free(xb);
    } else {
        ORB_FLAG_SET(orb, ORB_FG_PAUSE_INGRESS);
        orb->node.s_ingress = hud_orbit_process_ingress;
        hudnode_set_handler(&orb->node, hud_orbit_handler);
        orb->ingress_len += xb->len;
        hud_orbit_pushback_data(node, uf, xb, ORB_F_INGRESS);
    }
}

void
hud_orbit_pushback_egress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (ORB_FLAG_TEST(orb, ORB_FG_DROP_EGRESS | ORB_FG_FREE)) {
        /* Aborting or shutdown, just ignore this data */
        xbuf_free(xb);
    } else {
        ORB_FLAG_SET(orb, ORB_FG_PAUSE_EGRESS);
        orb->node.s_egress = hud_orbit_process_egress;
        hudnode_set_handler(&orb->node, hud_orbit_handler);
        hud_orbit_report_mu_delta(orb, uf, orb->egress_len + xb->len);
        hud_orbit_pushback_data(node, uf, xb, ORB_F_EGRESS);
    }
}

void
hud_orbit_late_insert(struct hudnode *node) {
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_INSERT);
}

void
hud_orbit_fallback(struct hudnode *node) {
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_UNSET(orb, ORB_FG_DROP_EGRESS);
    hud_orbit_check_egress_fastpath(orb);
    hud_orbit_check_handler_fastpath(orb);
}

void
hud_orbit_set_handler(struct hudnode *node, void *handler)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    orb->handler = handler;
}

void
hud_orbit_set_ingress_handler(struct hudnode *node, void *handler)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    orb->ingress_handler = handler;
}

void
hud_orbit_set_egress_handler(struct hudnode *node, void *handler)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    orb->egress_handler = handler;
}

void
hud_orbit_set_packet_mode(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    node->ingress = (void *)hud_orbit_process_ingress_pkt;
    node->egress = (void *)hud_orbit_process_egress_pkt;
    ORB_FLAG_SET(orb, ORB_FG_PACKET);
}

void
hud_orbit_accepted_handling(struct hudnode *node, union uflow *uf,
    BOOL val)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);

    if (val) {
        ORB_FLAG_SET(orb, ORB_FG_HOLD_ACCEPTED);
    } else {
        ORB_FLAG_UNSET(orb, ORB_FG_HOLD_ACCEPTED);
        if (ORB_FLAG_TEST(orb, ORB_FG_ACCEPTED)) {
            /* Send the HUDEVT_ACCEPTED when safe */
            hud_orbit_trigger_flush(orb, uf);
        }
    }
}

void
hud_orbit_hairpin_handling(struct hudnode *node, union uflow *uf, BOOL val)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    if (val) {
        ORB_FLAG_SET(orb, ORB_FG_HAIRPIN);
    }
}

/* This hudnode is the base of multiple flows, so flowcontrol is more complex */
