hud_orbit_notify_sent_unset(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_UNSET(orb, ORB_FG_NOTIFY_SENT);
}

void
hud_orbit_notify_xoff_set(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_NOTIFY_XOFF);
}

void
hud_orbit_sent_set(struct hudnode *node)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_SENT);
}

void
hud_orbit_drop_xoff_above_set(struct hudnode *node, union uflow *uf)
{
    struct hud_orbit *orb = HUDNODE_ORBIT(node);
    ORB_FLAG_SET(orb, ORB_FG_DROP_XOFF_ABOVE);
    ORB_FLAG_UNSET(orb, ORB_FG_XOFF_ABOVE);
    hud_orbit_apply_ingress_flow_control(orb, uf);
}

