static inline void
hud_orbit_entry_msg(struct hud_orb_entry *entry, hud_msg_t *msg, void **data)
{
    struct xbuf *xb = hud_orbit_entry_xb(entry);
    *msg = xb->mss;
    *data = xb->xfrag_head.tqh_first;
}

/* Get Hud Message type */
